/* YemAkıl veri tabloları (V122): parametre açıklamaları (EXP), premiks sorun bilgi tabanı (MKP, MKX). index.html'den önce yüklenir. */
var EXP={
"KM alımı, kg":{lo:["Hayvan ihtiyacından az kuru madde alıyor; enerji ve protein alımı birlikte düşer, önce süt/artış, sonra kondisyon kaybolur.","Yem miktarını kademeli artırın; yemlik boş kalmasın, yem önü ve su erişimini, yemin tazeliğini ve küflü/bozuk kısım olup olmadığını kontrol edin."],hi:["Beklenenden fazla yem görünüyor; ya hayvan gerçekten çok yiyor ya da yem artığı sayılmıyor. Fazla yem maliyet ve yağlanmadır.","Yemlik artığını 2–3 gün tartın; gerçek tüketimi girin. Artık yoksa hayvan sayısını ve tartım/süt kayıtlarını kontrol edin."],
 sut:{lo:["İnek yiyebileceğinden az yiyor; erken laktasyonda açık vücut rezervinden kapanır: ketozis, zayıflama, döl tutmama ve süt düşüşü gelir.","Önce yem miktarını artırın; sulu/ekşi silaj, ısınmış TMR, yemlik alanı (baş başına 60 cm) ve su kontrolü yapın. Tüketim 2 hafta içinde yükselmezse rasyonun lezzetini (küf, bozuk silaj) ve ayak sağlığını değerlendirin."]},
 besi:{lo:["Besi hayvanı az yediğinde günlük artış ve yem dönüşümü birlikte kötüleşir; besi süresi uzar, maliyet artar.","Yemi 2–3 öğüne bölün, yemlik boş kalmasın; sıcak havada sabah-akşam yemleme; artığı tartıp gerçek tüketimi girin."]},
 buzagi:{lo:["Buzağı katı yemi az yiyor; rumen gelişimi gecikir, sütten kesim zorlaşır.","Başlangıç yemini her gün taze ve az miktarda verin, su ilk günden önde olsun, süt miktarı çok yüksekse kademeli azaltın."]}},
"Rasyon KM, %":{lo:["Rasyon çok sulu: hacim rumeni doldurur, hayvan ihtiyacı kadar kuru madde alamaz; özellikle yüksek verimde tüketim sınırlanır.","Sulu silaj/posayı azaltıp kuru ot, saman veya kesif yemle kuru maddeyi yükseltin; silajın KM'sini ölçün."],hi:["Rasyon kuru ve tozlu: ayrışma (hayvan taneyi seçer) ve tüketim düşüşü olur; TMR homojen kalmaz.","TMR'ye su veya sulu yem (silaj, posa, melas) katın; hedef %45–55 KM."]},
"HP, %":{lo:["Ham protein düşük: rumen mikropları yeterli azot bulamaz, lif sindirimi yavaşlar; süt proteini ve verim ya da canlı ağırlık artışı düşer.","Küspe (soya, ayçiçeği, pamuk) veya proteinli kesif yem ekleyin; önce kaba yem kalitesini (yonca, iyi silaj) artırmayı düşünün."],hi:["Protein fazla: fazlası üreye çevrilip idrarla atılır; enerji harcanır, döl tutma ve ayak sağlığı bozulabilir, yem maliyeti boşa gider.","Küspe payını azaltın; proteini enerjiyle dengeleyin (tahıl/flake); azot verimliliğini izleyin."],
 koyun:{hi:["Protein fazla: kuzuda üre yükü ve yem maliyeti artar, artış ekstra protein ile yükselmez.","Küspe payını azaltın, enerjiyi (tahıl) artırın."]}},
"HP (katı), %":{lo:["Başlangıç/büyütme yemi proteini düşük: buzağıda kas ve iskelet gelişimi yavaşlar, enerji yağlanmaya gider.","%18–22 HP başlangıç yemi kullanın; soya küspesi ekleyin."],hi:["Protein fazla: pahalı ve gereksiz; ishal eğilimini artırabilir.","Daha düşük proteinli büyütme yemine geçin."]},
"HP (başlangıç yemi), %":{lo:["Başlangıç yemi proteini düşük: rumen gelişimi ve büyüme yavaşlar.","%18–22 HP başlangıç yemi kullanın."],hi:["Protein gereksiz yüksek; maliyet artar.","%18–22 HP yeterli."]},
"ME, Mcal/kg":{lo:["Enerji yoğunluğu düşük: hayvan rumen kapasitesiyle sınırlı yediği için ihtiyacını karşılayamaz; süt/artış düşer, kondisyon erir.","Tahıl, flake veya kesif yem payını artırın; samanı azaltıp daha iyi kaba yem (mısır silajı, kaliteli ot) kullanın."],hi:["Enerji yoğunluğu çok yüksek: rumen pH düşer (asidoz), lif sindirimi bozulur, süt yağı düşer; beside yağlanma ve karaciğer apsesi riski.","Kaba yemi artırın, tahılı azaltın; değişimi 7–10 günde kademeli yapın."]},
"Toplam ME, Mcal":{lo:["Toplam enerji hedef artış için yetmiyor: buzağı yavaş büyür, soğukta hastalık direnci düşer.","Süt/ikame miktarını (öğün ekleyerek) artırın veya başlangıç yemi alımını yükseltin; soğukta ek süt verin."],hi:["Enerji hedefin üstünde: fazlası yağlanmaya gider; süt çok yüksekse katı yem alımı gecikir.","Hedef artışa göre süt miktarını ayarlayın; sütten kesime yaklaşırken sütü kademeli azaltın."]},
"Nişasta, %":{lo:["Nişasta düşük: rumende hızlı enerji ve mikrobiyal protein az olur; süt proteini, canlı ağırlık artışı sınırlanır.","Tahıl (arpa, mısır, flake) veya nişastalı kesif yem ekleyin; kademeli artırın."],hi:["Nişasta yüksek: rumen asitleşir (SARA), süt yağı düşer, ayak sorunları ve beside karaciğer apsesi artar.","Tahılı azaltıp lifli yan ürün (pancar posası, kepek) ve uzun kıyımlı kaba yem ekleyin; tahılı ince öğütmeyin."],
 koyun:{hi:["Nişasta yüksek: kuzuda asidoz ve enterotoksemi (ani ölüm) riski.","Tahılı bütün/kaba kırılmış verin, kesifi kademeli artırın, aşıyı tamamlayın, kaba yem önde olsun."]}},
"Nişasta (katı), %":{lo:["Katı yemde nişasta düşük: rumen papilla gelişimi yavaşlar, sütten kesim gecikir.","Tahıl içeren tekstürlü başlangıç yemi kullanın."],hi:["Nişasta yüksek: sütten kesim sonrası asidoz ve ishal riski.","Nişastayı %35 altına çekin, biraz kuru ot ekleyin, pelet yerine tekstürlü yem tercih edin."]},
"NDF, %":{lo:["Lif düşük: geviş ve tükürük azalır, rumen pH düşer; süt yağı düşer, asidoz ve ayak sorunları gelir.","Uzun kıyımlı kaba yem (kuru ot, saman) ekleyin, kesifi azaltın."],hi:["Lif yüksek: rumen dolar, tüketim ve enerji alımı düşer; süt/artış sınırlanır.","Düşük kaliteli kaba yemi (saman) azaltın, daha sindirilebilir kaba yem ve kesif yem ekleyin."]},
"NDF (katı), %":{lo:["Katı yemde lif düşük: asidoz ve ishal riski.","%5–10 iyi kuru ot ekleyin veya lifli başlangıç yemi seçin."],hi:["Katı yem çok lifli: buzağı yeterli enerji alamaz, karın büyür, büyüme yavaşlar.","Kuru ot payını düşürün; başlangıç yemi lif değerini kontrol edin."]},
"ADF, %":{lo:["Sindirilmez lif az: rumen sağlığı için yapısal lif yetersiz kalabilir.","Lifli kaba yem ekleyin."],hi:["ADF yüksek: kaba yem odunlaşmış, sindirilebilirlik ve enerji düşük.","Geç hasat/samanı azaltın; daha erken biçilmiş ot, iyi silaj kullanın."]},
"Kaba, %":{lo:["Kaba yem az: rumen tamponu yetersiz, asidoz, şişme ve süt yağı düşüşü; beside apse riski.","Uzun kıyımlı kaba yem payını artırın; kesifi azaltın."],hi:["Kaba yem fazla: enerji yoğunluğu düşer, hayvan ihtiyacını karşılayamaz.","Kesif yem/tahıl payını kademeli artırın."]},
"Kaba (katı), %":{lo:["Kaba yem yok: sütten kesilmiş buzağıda rumen pH düşer, asidoz ve ishal gelir.","Katı yemin %5–10'u kadar iyi kuru ot/saman verin."],hi:["Kaba yem fazla: enerji ve protein alımı düşer, buzağı karınlı ve zayıf kalır.","Kuru otu azaltın, büyütme yemini artırın."]},
"Kaba yem (katı içinde), %":{hi:["Süt dönemi buzağıda fazla kaba yem: rumen gelişimini (papilla) geciktirir, karın büyür.","Sütten kesim öncesi kaba yemi %5–10 ile sınırlayın; 3. haftadan önce vermeyin."]},
"Kesif, %":{lo:["Kesif yem az: enerji yetersiz kalabilir.","Kesif yemi kademeli artırın."],hi:["Kesif yem çok: asidoz riski.","Kaba yemi artırın."]},
"Kaba yem NDF, %":{lo:["Kaba yemden gelen lif az: etkili lif (geviş) yetersiz; süt yağı düşer, asidoz riski.","Uzun kıyımlı kuru ot/saman ekleyin; TMR'yi fazla kıymayın."],hi:["Kaba yem lifi çok yüksek: tüketim düşer, enerji alımı sınırlanır.","Samanı azaltın, kaliteli kaba yem kullanın."]},
"Ham yağ, %":{lo:["Ham yağ (ether ekstrakt) rasyonun yoğun enerji kaynağıdır; tahıl ve küspe ağırlıklı rasyonlarda %2–3 doğal yağ vardır. Düşükse enerji yoğunluğu sınırlı kalır, yüksek verimde kondisyon kaybı artar.","Yağlı tohum (tam yağlı soya, bütün pamuk tohumu, ayçiçeği), DDGS veya bypass yağ ekleyin; toplam yağ %6–7'yi geçmesin."],hi:["Yağ fazla (özellikle doymamış bitkisel yağ): rumen mikroplarını ve lif sindirimini bozar, süt yağı düşer, yem tüketimi azalır; beside karkas yağlanması artar.","Yağlı tohum/bypass yağ payını azaltın; serbest yağı %3–4 KM'nin üstüne çıkarmayın, gerekirse korunmuş (kalsiyum sabunu) yağ kullanın."]},
"peNDF, %":{lo:["peNDF (fiziksel etkin lif), hayvanı geviş getirmeye zorlayan uzun parçalı liftir. Geviş = tükürük = rumenin doğal tamponu. peNDF düşükse rumen pH düşer: süt yağı düşer, asidoz, ishal, topallık ve yem seçme başlar; lif toplamda yeterli görünse bile.","Uzun kıyımlı kaba yem ekleyin (1–2 kg kuru ot/saman, 4–5 cm kıyım), TMR'yi fazla karıştırmayın, tahılı ince öğütmek yerine kırın; elek testinde üst elek %6–10 olmalı. Gerekirse sodyum bikarbonat (150–250 g) ile tamponlayın."],hi:["Etkili lif çok yüksek: rumen dolar, tüketim ve enerji alımı düşer; süt/artış sınırlanır.","Kaba yemi biraz azaltın veya daha kısa kıyın; kesif yemi artırın."]},
"Kalsiyum, %":{lo:["Kalsiyum düşük: süt, kemik ve kas işlevi için eksik; sağmalda süt düşer, gebe/doğum sonrası hipokalsemi riski.","Kireç taşı (kalsiyum karbonat) ekleyin; yonca da iyi bir Ca kaynağıdır."],hi:["Kalsiyum fazla: diğer minerallerin (P, Mg, Zn) emilimini bozar; kuru dönemde süt humması riskini artırır.","Mineral/kireç taşı payını azaltın."],
 sut:{hi:["Kalsiyum fazla: fosfor, magnezyum ve çinko emilimi düşer; kuru dönemde yüksek Ca ineğin kendi Ca düzenini tembelleştirir, süt humması gelir.","Kireç taşını ve yoncayı azaltın; yakın dönemde Ca %0,6 altı (anyonik programda %1,0–1,5)."]}},
"Kalsiyum (katı), %":{lo:["Kalsiyum düşük: iskelet gelişimi yavaşlar.","Başlangıç yemine kireç taşı/mineral ekleyin."],hi:["Kalsiyum fazla: fosfor ve çinko emilimi bozulur.","Mineral payını azaltın."]},
"Fosfor, %":{lo:["Fosfor düşük: enerji metabolizması, kemik ve döl verimi için kritik; kızgınlık zayıflar, döl tutma gecikir, verim düşer.","Dikalsiyum fosfat veya kepek/küspe gibi fosforlu yem ekleyin."],hi:["Fosfor fazla: pahalıdır, Ca:P dengesini bozar; erkek hayvanda idrar taşı, kuru dönemde süt humması riski.","Fosfat kaynağını ve kepek/küspe payını azaltın; Ca:P 1,5–2:1 tutun."]},
"Fosfor (katı), %":{lo:["Fosfor düşük: kemik gelişimi ve iştah düşer.","Dikalsiyum fosfat ekleyin."],hi:["Fosfor fazla: gereksiz maliyet, Ca:P bozulur.","Fosfat payını azaltın."]},
"Ca:P oranı":{lo:["Kalsiyum fosfora göre az: erkeklerde fosfat taşı (idrar yolu tıkanması, ani ölüm) riski; kemik mineralizasyonu bozulur.","Kireç taşı ekleyip oranı 2:1'e çıkarın; fosfatı azaltın, tuz %0,5–1, su bol olsun."],hi:["Ca:P çok yüksek: fosfor eksikliği ve mineral emilim sorunları.","Kireç taşını azaltın, fosfor kaynağı ekleyin."]},
"Sıvı KM, kg":{lo:["Süt kuru maddesi NASEM alt sınırının altında: buzağı aç kalır, büyüme ve bağışıklık düşer, hastalık ve ölüm artar.","Günlük sütü doğum ağırlığının en az %1,5'i kadar kuru madde olacak şekilde artırın; 3 öğüne bölün."],hi:["Süt kuru maddesi çok yüksek: sindirim yükü ve ishal riski, katı yem alımı gecikir.","Sütü hedef artışa göre azaltın, ikame oranını %15'i geçirmeyin."]},
"Süt / sulu ikame, L/gün":{lo:["Süt az: buzağı doğum ağırlığının iki katına 56 günde ulaşamaz, bağışıklık düşer, ishal ve solunum hastalığı artar.","Sütü canlı ağırlığın %15–20'sine çıkarın (3 öğün); soğukta daha fazla."],hi:["Süt çok fazla: ozmotik ishal ve abomazum şişmesi riski, katı yem alımı gecikir.","Öğün sayısını artırın (3 öğün); 6. haftadan sonra kademeli azaltın."]},
"Başlangıç yemi KM, kg":{lo:["Başlangıç yemi tüketimi beklenenin altında: rumen gelişimi gecikir, sütten kesimde büyüme duraklar (kesim şoku).","Yemi her gün taze ve az verin, su ilk günden önde olsun; süt çok yüksekse kademeli azaltın; tekstürlü, lezzetli yem seçin."],hi:["Başlangıç yemi beklenenin çok üstünde görünüyor: yem artığı tüketim sayılmış olabilir.","Artığı tartın; gerçekse sütten kesime hazır demektir."]},
"Katı yem KM, kg":{lo:["Sütten kesilmiş buzağı az katı yem yiyor: büyüme hedefin altında kalır, düve yaşı uzar.","Büyütme yemini serbest verin, suyu ve yemlik alanını kontrol edin; grup stresini azaltın."],hi:["Tüketim beklenenin üstünde: yem artığı sayılıyor olabilir.","Artığı tartıp gerçek tüketimi girin."]},
"İkame yemi HP, %":{lo:["Süt ikame proteini düşük: büyüme protein ile sınırlanır.","%22–26 HP ikame yemi kullanın."],hi:["Protein yüksek; maliyet artar.","%22–26 HP yeterli."]},
"Metabolik protein, g":{lo:["Metabolik protein (MP), bağırsaktan emilen ve süt/kas yapımında kullanılan proteindir; iki kaynağı var: rumen mikroplarının ürettiği protein ve rumende parçalanmadan geçen (bypass) yem proteini. MP yetersizse ham protein yeterli görünse bile süt proteini ve süt verimi düşer, erken laktasyonda inek kendi kasını yıkar.","Bypass proteini yüksek bir kaynak ekleyin: soya küspesi (1–1,5 kg), mısır gluteni (0,5 kg), DDGS veya Yemcibey Protein Kardeşliği; Çözüm asistanı miktarı hesaplar. Kaba yem kalitesini yükseltmek (iyi silaj, yonca) mikrobiyal proteini de artırır."],hi:["MP ihtiyacın üstünde: fazla protein süte dönüşmez, karaciğerde üreye çevrilip idrarla atılır; bu hem enerji harcatır hem döl tutmayı ve ayak sağlığını bozar, hem de en pahalı hammaddeyi boşa harcar.","Küspe/protein yemi payını azaltın; Çözüm asistanı en ucuz dengeyi verir. Azot verimliliği ve süt üre azotu (MUN) takibi yapın."]},
"RDP, g":{lo:["RDP, rumende çözünen proteindir; rumen mikropları bu azotla çoğalır ve lifi sindirir. RDP azsa mikroplar aç kalır: lif sindirimi yavaşlar, yem tüketimi düşer, mikrobiyal protein (en kaliteli protein kaynağı) azalır. Ham protein yeterli görünse de süt düşer.","Çözünür protein kaynağı ekleyin: yonca, ayçiçeği küspesi, kolza; en ucuzu yem üresidir (günde en çok 150 g/inek, 2 haftada kademeli, TMR'de homojen karıştırılmalı). Aşağıdaki katkı önerisi gramı hesaplar."],hi:["RDP fazla: mikropların kullanamadığı azot amonyak olarak emilir, karaciğerde üreye çevrilir; süt üresi yükselir, döl tutma düşer, enerji boşa gider.","Çözünür protein kaynaklarını (üre, yonca, taze yeşil yem) azaltın; bypass proteini yüksek kaynaklara kayın."]},
"RUP, % HP":{lo:["RUP (bypass protein), rumende parçalanmadan bağırsağa geçen protein payıdır. Yüksek verimli inekte mikrobiyal protein tek başına yetmez; bypass payı düşükse süt proteini sınırlanır.","Soya küspesi, mısır gluteni, DDGS, pamuk tohumu küspesi gibi bypass payı yüksek hammaddeler kullanın; ısıl işlemli soya (tam yağlı kavrulmuş) da bypass artırır."],hi:["Bypass payı çok yüksek: rumen mikropları için çözünür azot az kalabilir; lif sindirimi düşer.","Yonca, ayçiçeği küspesi gibi çözünür kaynaklarla dengeleyin."]},
"Lizin, % MP":{lo:["Lizin, süt proteini yapımında en çok sınırlayan iki amino asitten biridir (diğeri metiyonin). Mısır ve mısır silajı ağırlıklı rasyonlarda lizin düşük kalır; protein toplamda yeterli olsa bile süt proteini yükselmez, fazla protein boşa gider.","Lizin zengini protein kaynakları ekleyin: soya küspesi, kanola küspesi, balık unu; mısır gluteni ve DDGS lizin fakiridir. Hızlı çözüm korunmuş (bypass) lizin ürünüdür: günde 40–80 g (etiketteki emilen lizin oranına göre). Hedef Lys:Met 3:1."]},
"Metiyonin, % MP":{lo:["Metiyonin, süt proteini ve süt yağı sentezi ile karaciğerin yağ taşıması için gerekli amino asittir; soya ağırlıklı rasyonlarda ilk sınırlayan odur. Eksikse süt proteini düşer, erken laktasyonda karaciğer yağlanması ve ketozis riski artar.","Metiyonin zengini kaynaklar: mısır gluteni, kolza/kanola küspesi, balık unu. Hızlı ve kesin çözüm korunmuş (bypass) metiyonin ürünü: günde 10–25 g (etiketteki emilen metiyonin oranına göre). Lys:Met 3:1 hedeflenir."]},
"DCAD, mEq/kg":{lo:["DCAD, rasyondaki katyon (sodyum, potasyum) ile anyonların (klor, kükürt) farkıdır; kanın asit–baz dengesini belirler. Sağmal inekte DCAD düşükse (asidik yük) yem tüketimi, süt yağı ve süt verimi düşer. Kuru dönemin son 3 haftasında ise düşük/negatif DCAD istenir (anyonik program): ineğin kalsiyum düzenini doğumdan önce uyandırır, süt hummasını önler.","Sağmal inekte sodyum bikarbonat (150–250 g/gün) ve gerekirse potasyum karbonat ekleyin; aşağıdaki katkı önerisi gramı verir. Yakın dönemde ise bu düşüklük istenen durumdur: idrar pH 6,0–6,8 ve rasyon Ca %1,0–1,5 kontrol edin."],hi:["DCAD yüksek (çok potasyum/sodyum): yakın dönem ineğinde kan Ca düzeni tembelleşir, doğumda kan kalsiyumu çöker (süt humması); ardından ketozis, sonun atılamaması, abomazum kayması gelir. Yüksek DCAD'ın ana kaynağı potasyumu yüksek kaba yemlerdir (yonca, taze ot, melas).","Önce potasyumu düşürün: yonca ve melası azaltın, saman ve mısır silajı kullanın (hedef K < %1,3). Yetmezse anyonik tuz (kalsiyum klorür, magnezyum sülfat veya hazır anyonik ürün) ile DCAD'ı −50…−100 mEq/kg'a çekin; idrar pH 6,0–6,8 olana kadar dozu ayarlayın, Ca'yı %1,0–1,5'e çıkarın, lezzet için melas ile karıştırın. Katkı önerisi gramları hesaplar."],sut:{hi:["Sağmal inekte yüksek DCAD sorun değildir; yalnızca gereksiz mineral maliyeti olabilir.","Değişiklik gerekmez."]}},
"Potasyum, %":{lo:["Potasyum, hücre içi ana mineraldir; süte bol geçer ve sıcakta terle kaybedilir. Eksikse iştah ve süt düşer, sıcak stresinde inek daha çok etkilenir. Tahıl ağırlıklı, yoncasız rasyonlarda düşük kalır.","Yonca/kaliteli kuru ot ekleyin veya potasyum karbonat (100–200 g/gün, sıcak mevsimde) kullanın; aşağıda gram verilir."],hi:["Potasyum yüksek: magnezyum emilimini engeller (tetani, süt yağı düşüşü), kuru dönemde ise süt hummasının bir numaralı nedenidir. Kaynağı genelde yonca, taze yeşil yem, melas ve gübreyle beslenen kaba yemlerdir.","Kuru dönemde yonca ve melası kesin/azaltın, saman ve mısır silajı kullanın (K < %1,3). Sağmalda sorun değil ama magnezyumu %0,3'e çıkarın."]},
"Magnezyum, %":{lo:["Magnezyum, kalsiyumun kemikten çözülmesi ve emilmesi için gereken hormon sisteminin anahtarıdır; ayrıca kas–sinir iletimi ve rumen mikrop çalışması için gerekir. Eksikse: kuru dönemde süt humması, sağmalda süt yağı düşüşü, meraya çıkışta çayır tetanisi (titreme, düşme).","Magnezyum oksit (MgO, %54 Mg) ekleyin: sağmalda 30–50 g/gün, yakın dönemde rasyon %0,35–0,40 Mg olacak şekilde 50–80 g; aşağıda gram verilir. MgO lezzetsizdir, TMR'ye iyi karıştırın; potasyum yüksekse ihtiyaç artar."],hi:["Magnezyum çok yüksek: ishal ve tüketim düşüşü yapar; genelde fazla MgO veya magnezyum sülfattan gelir.","MgO/MgSO₄ dozunu azaltın."]},
"Kükürt, %":{lo:["Kükürt, rumen mikroplarının kükürtlü amino asit (metiyonin) üretmesi için gerekir; özellikle üre kullanılıyorsa eksikliği mikrobiyal proteini sınırlar.","Magnezyum sülfat veya amonyum sülfat ekleyin (aşağıda gram); üre kullanıyorsanız azot:kükürt oranı 10–12:1 olmalı."],hi:["Kükürt fazla: rumende hidrojen sülfür oluşur, beyinde polioensefalomalasi (PEM: körlük, baş basma, ani ölüm) yapar; bakır ve selenyum emilimini de engeller. Kaynağı DDGS, melas, mısır gluteni, kükürtlü su ve bazı mineral karışımlarıdır.","DDGS/melas/mısır gluteni payını azaltın, suyun sülfatını ölçtürün; toplam S %0,3'ün altına inene kadar kükürtlü katkı vermeyin; tiamin desteği için veterinere danışın."]},
"Sodyum, %":{lo:["Sodyum, su dengesi ve iştahın anahtarıdır; tükürükle rumene döner ve tampon görevi görür. Çoğu yem sodyum fakiridir; tuz verilmezse iştah ve su tüketimi düşer, süt azalır, hayvanlar toprak/duvar yalar.","Tuz ekleyin: sağmal inek 80–120 g/gün (rasyonun %0,3–0,5'i), besi 30–50 g, koyun 7–10 g; aşağıda gram verilir. Yalama taşı tek başına genelde yetmez."],hi:["Sodyum fazla: su tüketimi artar, kuru dönemde meme ödemi riski; genelde fazla tuz veya bikarbonattan gelir.","Tuz/bikarbonat payını azaltın; yakın dönemde tuzu 30 g'ın altında tutun."]},
"Bakır, mg/kg":{lo:["Bakır, bağışıklık, döl tutma, kemik ve tüy/yapağı pigmenti için gerekir; kaba yemler genelde bakır fakiridir, molibden ve kükürt yüksekse emilimi daha da düşer. Eksiklikte kızgınlık görülmez, tüy kızarır/donuklaşır, ishal ve zayıflama olur, buzağıda büyüme geriler.","İz mineral premiksi (bakır, çinko, selenyum içeren) kullanın; tek başına bakır sülfat vermek dozaj hatasına açıktır (aşağıda hesaplanan gram küçük olduğundan premiksle karıştırın)."],hi:["Bakır fazla: karaciğerde birikir; sığır toleranslıdır ama uzun vadede karaciğer hasarı yapar.","Premiks/bakır sülfat dozunu azaltın."],koyun:{hi:["Koyun bakıra sığırdan 10 kat duyarlıdır: fazlası haftalarca karaciğerde sessizce birikir, sonra stresle birlikte ani hemoliz (sarı mukoza, kahverengi idrar, ölüm) başlar. Kaynağı çoğu zaman sığır yemi, sığır premiksi veya bakır sülfatlı mineraldir.","Sığır yemini ve sığır premiksini hemen kesin; koyuna özel yem/mineral (Cu 5–10 mg/kg) kullanın; şüphede molibden-kükürt desteği için veterinere danışın."]}},
"Çinko, mg/kg":{lo:["Çinko, tırnak boynuzu, deri, yara iyileşmesi, bağışıklık ve döl verimi için gerekir; yemlerin çoğu sınırda kalır. Eksiklikte topallık (tırnak çürüğü), kaba tüy, mastitis ve yavaş iyileşen yaralar artar, kızgınlık zayıflar.","Çinko içeren iz mineral premiksi kullanın; hesaplanan çinko sülfat gramı aşağıdadır (tek başına verilecekse tartarak premikse karıştırın). Ayak sorunu olan sürüde organik (kelatlı) çinko tercih edilir."],hi:["Çinko fazla: bakır emilimini engeller.","Premiks dozunu azaltın."]},
"Selenyum, mg/kg":{lo:["Selenyum, E vitaminiyle birlikte hücreleri koruyan antioksidan sistemin parçasıdır; Türkiye topraklarının çoğu selenyum fakir olduğundan yemlerde düşüktür. Eksiklikte sonun atılamaması (retensiyo), mastitis, zayıf doğan ve ayağa kalkamayan buzağı/kuzu (beyaz kas hastalığı), döl tutmama görülür.","Selenyum ve E vitamini içeren premiks kullanın (sağmal inekte ~5–7 mg Se/gün); aşağıda ihtiyaç mg olarak ve etiket değerine göre premiks gramı verilir. Selenyumu asla sodyum selenit olarak elle dozlamayın: zehirlenme sınırı dardır. Doğum öncesi Se+E enjeksiyonu için veterinere danışın."],hi:["Selenyum fazla: 2–5 mg/kg üstü zehirlidir (kıl dökülmesi, tırnak deformasyonu, topallık).","Premiks selenyum dozunu azaltın."]}
};
var MKP=[ /* sorunlar */
 {k:"tirnak",n:"Tırnak sorunları / topallık",a:["sut","besi","koyun"],why:"Topallığın üç kaynağı: (1) subakut rumen asidozu (SARA) → laminitis: hızlı nişasta, az etkili lif; (2) tırnak boynuzunu yapan besinlerin eksikliği: biotin, çinko, bakır, iyot; (3) ıslak-pis zemin ve dermatitis (ayak banyosu). Katkı 2 ve 3'e yardım eder; 1'i rasyon düzeltir.",sign:"Sırt kamburu, kısa adım, sole ülseri, beyaz çizgi ayrılması, topuk siğili; sürüde %10'dan fazla topal hayvan.",chk:"Rasyon sekmesinde: nişasta sağmalda toplam %26'nın altında, peNDF %20'nin üstünde, Zn 60 mg/kg, Cu 12–15 mg/kg olmalı.",items:[["biotin",1,"20 mg biotin/gün; etkisi 4–6 ayda görülür (tırnak büyüme süresi); süt verimine de +1 kg","A"],["znorg",4,"400 mg organik Zn: keratin sentezi, topuk siğili ve sole ülseri azalır (Zinpro araştırmaları, Hutjens fayda:maliyet 14:1)","A"],["cu",0.5,"125 mg Cu (koyunda vermeyin)","B"],["iod",1,"10 mg I: ayak çürüğü ve dermatitis direnci","B"],["bik",150,"SARA şüphesinde tampon; 2–3 hafta","A"]],time:"Tampon 1–2 hafta; biotin/çinko 3–6 ay (yeni tırnak boynuzu).",koyun:[["biotin",0.3,"6 mg biotin/gün (koyun)","B"],["znorg",1,"100 mg Zn","A"],["iod",0.3,"3 mg I","B"]]},
 {k:"sutyag",n:"Süt yağı düşüklüğü",a:["sut"],why:"Süt yağı rumende asetat ve bütirattan yapılır; bunlar lif sindiriminden gelir. Rumen pH düşünce (hızlı nişasta, az lif, ince kıyım) ve doymamış yağ fazlayken (DDGS, yağlı tohum) rumende 'trans-10' yağ asitleri oluşur ve meme yağ sentezini durdurur (süt yağı depresyonu).",sign:"Süt yağı %3,5 altı veya yağ:protein oranı 1,0'ın altında; dışkı sulu; geviş azalmış.",chk:"Nişasta < %26, peNDF > %20–22, kaba yem NDF > %19, toplam yağ < %6, doymamış yağ (DDGS+yağlı tohum) sınırlı; TMR kıyım 4–5 cm.",items:[["bik",200,"rumen pH tamponu; süt yağına +0,2–0,3 puan (Hutjens fayda:maliyet 4–12:1)","A"],["mgo",70,"Mg + tampon; bikarbonat:MgO 2–3:1","A"],["yeast",20,"lif sindiren bakterileri uyarır, laktik asidi kullanır","A"],["casoap",300,"korunmuş yağ: rumeni bozmadan süt yağına substrat","B"]],time:"Tampon ve maya 7–14 gün; rasyon lif düzeltmesi 2–3 hafta."},
 {k:"sutpro",n:"Süt proteini düşüklüğü",a:["sut"],why:"Süt proteini önce enerjiye (rumende propiyonat → glikoz), sonra emilen amino asit dengesine (lizin, metiyonin) bağlıdır. Ham protein yüksek olsa bile enerji veya ilk sınırlayan amino asit eksikse süt proteini yükselmez.",sign:"Süt proteini %3,0–3,1 altı; MUN yüksekse protein var ama enerji yok demektir.",chk:"Nişasta %22–26, ME ve NEL dengesi pozitif, metabolik protein yeterli, Lys %6,8–7,2 ve Met %2,3–2,4 MP (Rasyon sekmesi protein ayrıntısı).",items:[["met",20,"korunmuş metiyonin: süt proteini +0,1–0,15 puan","A"],["lys",60,"mısır ağırlıklı rasyonda lizin","B"],["yeast",20,"mikrobiyal protein artışı","B"]],time:"2–4 hafta."},
 {k:"dol",n:"Döl tutmama / tekrar tohumlama",a:["sut","besi","koyun"],why:"Döl tutma dört ayağa basar: enerji dengesi (negatif dengede yumurtalık uyur), mineral-vitamin (Se, E, A/β-karoten, Cu, Mn, Zn, I), protein fazlası (yüksek MUN embriyoyu öldürür) ve sağlık (metritis). Katkılar ikinci ayağı düzeltir; birinci ve üçüncü rasyonla çözülür.",sign:"İlk tohumlamada gebelik %40 altı, servis başına >2,5 tohumlama, kistik yumurtalık, erken embriyo ölümü (21–25 günde tekrar kızgınlık).",chk:"NEL dengesi pozitif, MUN 10–14 mg/dl (HP ve RDP fazlası yok), P %0,35–0,40, Se 0,3 mg/kg, Cu 12–15, Mn 40–50, Zn 60, I 0,5 mg/kg.",items:[["bcar",4,"400 mg β-karoten: korpus luteum ve progesteron; mısır silajı/samanlı rasyonlarda düşük","B"],["seorg",2,"4 mg Se organik: yumurta kalitesi, metritis azalır","A"],["vitE",2,"1.000 IU E","A"],["vitA",0.1,"100.000 IU A","A"],["mn",0.5,"300 mg Mn: kızgınlık ve ovulasyon","B"],["cu",0.5,"125 mg Cu (koyunda vermeyin)","B"],["iod",1,"10 mg I: tiroit–üreme ekseni","B"],["flax",300,"omega-3: embriyo yaşama oranı; tohumlamadan 3 hafta önce başlayın","B"],["cr",10,"4 mg Cr: insülin duyarlılığı, enerji dengesi","B"]],time:"Mineral-vitamin 6–8 hafta (folikül gelişim süresi); etkisini ancak sonraki kızgınlık döngülerinde görürsünüz.",koyun:[["seorg",0.3,"0,6 mg Se","A"],["vitE",0.3,"150 IU E","A"],["vitA",0.02,"20.000 IU A","A"],["mn",0.1,"60 mg Mn","B"],["iod",0.3,"3 mg I","B"]]},
 {k:"kizg",n:"Kızgınlık göstermeme (sessiz kızgınlık)",a:["sut","besi","koyun"],why:"Anöstrusun bir numaralı nedeni negatif enerji dengesidir: inek erirken beyin üreme hormonlarını kapatır. İkinci neden fosfor, β-karoten, mangan, bakır ve iyot eksikliği; üçüncü neden topallık ve ayakta duramama (davranışsal).",sign:"Doğumdan 60 gün sonra hâlâ kızgınlık yok; kondisyon 2,5'in altına düşmüş; topallık.",chk:"Kondisyon kaybı 0,5 puanı geçmesin; ME/NEL dengesi; P %0,35–0,40; β-karoten kaynağı (yeşil yem, iyi silaj) var mı?",items:[["bcar",4,"400 mg β-karoten","B"],["dcp",60,"fosfor açığı varsa (P %0,35 altı) 60 g DCP","B"],["mn",0.5,"300 mg Mn","B"],["cu",0.5,"125 mg Cu","B"],["iod",1,"10 mg I","B"],["rpc",60,"erken laktasyonda enerji dengesi için korunmuş kolin (ketozis bölümüyle birlikte)","B"],["cr",10,"4 mg Cr","B"]],time:"4–8 hafta.",koyun:[["bcar",0.5,"50 mg β-karoten","B"],["mn",0.1,"60 mg Mn","B"],["iod",0.3,"3 mg I","B"]]},
 {k:"asidoz",n:"Asidoz / SARA",a:["sut","besi","koyun"],why:"Hızlı çözünen nişasta (arpa, buğday, ince öğütülmüş mısır) rumende laktik asit üretir; etkili lif azsa tükürük tamponu yetmez ve pH 5,5'in altına iner. Sonuç: lif sindiren bakteriler ölür, rumen duvarı zedelenir (laminitis, karaciğer apsesi), süt yağı düşer.",sign:"Dışkı sulu/köpüklü ve içinde tane, yem seçme, geviş azlığı, iştah dalgalanması, topallık, süt yağı düşüşü; beside ani ölüm/şişme.",chk:"Nişasta sağmal %22–26 / besi ≤ %40, peNDF ≥ %20, kaba yem ≥ %40 (sağmal), tahıl kaba kırılmış, tahıl artışı haftada en çok 0,5 kg.",items:[["bik",200,"tampon; rumen pH +0,2–0,3","A"],["mgo",70,"ikinci tampon + Mg","A"],["yeast",20,"laktik asidi kullanan bakterileri besler","A"],["asp",3,"rumen stabilizasyonu","B"],["mon",300,"iyonofor: laktik asit üreten bakterileri baskılar — veteriner reçetesi","A"],["tox",50,"bentonit/kil: pH tamponu ve toksin bağlama","B"]],time:"3–7 gün; rasyon düzeltmesi şart.",besi:[["bik",120,"besi: %0,75 KM tampon","A"],["mon",300,"iyonofor (reçeteli)","A"],["yeast",15,"maya","A"],["tox",40,"bentonit","B"]],koyun:[["bik",15,"koyun: 15 g","A"],["yeast",3,"maya","A"]]},
 {k:"ketoz",n:"Ketozis / yağlı karaciğer / zayıflama",a:["sut","koyun"],why:"Doğum sonrası iştah yeterince hızlı artmaz; inek vücut yağını eritir, karaciğer bu yağı işleyemez (yağlı karaciğer) ve keton cisimleri birikir. Kolin karaciğerden yağ taşıyan proteini (VLDL) yapar; propilen glikol ve propiyonat glikoz verir; niasin yağ erimesini frenler. Koyunda gebelik toksemisi aynı mekanizmadır (ikiz gebe, son 6 hafta).",sign:"Doğum sonrası 1–6 hafta: iştahsızlık (önce kesifi bırakır), hızlı zayıflama, nefeste/sütte aseton kokusu, kan BHB > 1,2 mmol/L, süt yağ:protein > 1,4; abomazum kayması.",chk:"Close-up KM alımı (≥ 12 kg), kuru dönem kondisyonu 3,0–3,5 (yağlı inek risklidir), doğum sonrası ME yoğunluğu, nişasta %24–26, yemlik alanı.",items:[["rpc",60,"15 g kolin: doğum öncesi 3 hafta – sonrası 6 hafta; ketozis ve yağlı karaciğeri azaltır (meta-analiz: süt +1,5–2 kg)","A"],["nia",12,"12 g niasin doğum öncesi 2 hafta – sonrası 4 hafta (korumasız form); korunmuşsa 3 g","B"],["pg",300,"300 ml/gün 5–7 gün: tedavi ve risklide koruma","A"],["capro",150,"glikoz + Ca: doğumdan 7 gün önce – 7 gün sonra","A"],["mon",300,"iyonofor: propiyonat artışı, ketozis −%25 (reçeteli)","A"],["met",15,"korunmuş metiyonin: karaciğer yağ taşıma","B"],["cr",10,"4 mg Cr: insülin duyarlılığı","B"]],time:"PG 1–3 gün; kolin/niasin koruyucu (programlı).",koyun:[["pg",120,"gebelik toksemisi: 2 × 60 ml/gün, 3–5 gün","A"],["nia",1,"1 g","B"],["capro",20,"20 g","B"]]},
 {k:"humma",n:"Süt humması (doğum felci) / hipokalsemi",a:["sut","koyun"],why:"Doğumda süte kalsiyum çekilince kan Ca düşer; kuru dönemde yüksek potasyum (yonca, taze ot) ve yüksek Ca, ineğin kemikten Ca çözme mekanizmasını uyutur. Çözüm: close-up rasyonda DCAD'ı düşürmek (anyonik tuz) ve Mg'yi yükseltmek; doğumda Ca bolusu.",sign:"Doğumdan 0–48 saat sonra yatma, soğuk kulak, 'S' boyun; sürüde subklinik (yatmayan ama ketozis, retensiyo, abomazum kayması artan) hipokalsemi.",chk:"Close-up: K < %1,3, DCAD −50…−150 mEq/kg, Mg %0,35–0,40, Ca %1,0–1,5 (anyonik programda), idrar pH 6,0–6,8.",items:[["anion",200,"anyonik tuz: 100 g CaCl₂ + 100 g MgSO₄ veya hazır ürün; 3 hafta prepartum; lezzet için melasla","A"],["mgo",60,"Mg %0,4 için","A"],["vitD",0.05,"25.000 IU D3","A"],["cabol",2,"doğumda + 12 saat sonra (3+ doğumlu ineklere)","A"]],time:"Anyonik program 7–10 günde idrar pH ile kontrol; bolus anında.",koyun:[["mgo",5,"5 g MgO (2,7 g Mg)","A"],["vitD",0.01,"5.000 IU","A"]]},
 {k:"retens",n:"Sonun atılamaması (retensiyo) / metritis",a:["sut","koyun"],why:"Plasentanın atılması bağışıklık hücrelerinin (nötrofil) işidir; selenyum ve E vitamini bu hücrelerin gücüdür. Hipokalsemi (uterus kasılması zayıf), ketozis, ikiz/güç doğum ve A vitamini eksikliği de nedendir.",sign:"24 saatte son atılmamış; doğum sonrası 5–10 günde kötü kokulu akıntı, ateş, süt düşüşü. Sürüde >%8 retensiyo.",chk:"Se 0,3 mg/kg, E vitamini close-up 2.000 IU/gün, A 100.000 IU, close-up DCAD/Mg (humma bölümü), kondisyon.",items:[["seorg",3,"6 mg Se organik (ya da enjeksiyon: veteriner), doğumdan 3–4 hafta önce","A"],["vitE",4,"2.000 IU E close-up 3 hafta; sonra 1.000 IU","A"],["vitA",0.1,"100.000 IU A","A"],["anion",200,"hipokalsemi bağlantısı: anyonik program","A"]],time:"Sonraki doğumlarda; program doğumdan 3–4 hafta önce başlamalı.",koyun:[["seorg",0.3,"0,6 mg Se","A"],["vitE",0.4,"200 IU E","A"]]},
 {k:"mastit",n:"Mastitis / yüksek somatik hücre",a:["sut","koyun"],why:"Memeyi savunan hücrelerin (nötrofil/makrofaj) gücü Se, E ve A vitamini, çinko ve bakıra bağlıdır. Sağım hijyeni, yatak kuruluğu ve sağım makinesi ilk sırada; katkı savunmayı güçlendirir, hijyeni ikame etmez.",sign:"Tank somatik hücre > 300.000, klinik vaka > %2/ay, kuru dönem sonrası yeni enfeksiyon.",chk:"Se 0,3 mg/kg, E 1.000 IU (sağmal) / 2.000 IU (close-up), Zn 60, Cu 12–15 mg/kg; DCAD pozitif (sağmal).",items:[["vitE",2,"1.000 IU E (close-up 4 g = 2.000 IU): klinik mastitis −%30 (Weiss)","A"],["seorg",2,"4 mg Se organik; sütle yavruya da geçer","A"],["znorg",4,"400 mg Zn: meme başı kanalı keratini, SHS düşer","A"],["cu",0.5,"125 mg Cu","B"],["vitA",0.1,"100.000 IU A / β-karoten","B"]],time:"4–8 hafta; yeni enfeksiyonlar azalır, eski kronikler kalır.",koyun:[["vitE",0.4,"200 IU","A"],["seorg",0.3,"0,6 mg Se","A"],["znorg",1,"100 mg Zn","A"]]},
 {k:"sicak",n:"Sıcak stresi (yaz)",a:["sut","besi","koyun"],why:"THI 68'i geçince inek yemi azaltır, solur (CO₂ kaybı → kan alkalozu), terle potasyum ve sodyum kaybeder, rumen pH düşer (gün içinde yem seçerek yer). Katkılar mineral kaybını ve rumen dengesini düzeltir; gölge, fan ve su birinci sıradadır.",sign:"Solunum > 60/dk, ayakta durma, süt −%10–25, süt yağı düşüşü, döl tutma düşüşü, su tüketimi artışı.",chk:"K %1,5–1,6, Na %0,45–0,6, Mg %0,35, DCAD +350–450 mEq/kg; yemi serin saatlerde verin; su 4 cm/baş, gölge.",items:[["kco3",150,"potasyum karbonat: terle kaybedilen K, DCAD yükseltir","A"],["bik",200,"sodyum bikarbonat: Na + tampon","A"],["mgo",50,"Mg","A"],["yeast",30,"rumen stabilitesi, KM alımı +0,5 kg","A"],["nia",12,"niasin: deri kan akımı/soğuma (12 g; korunmuş 3–6 g)","B"],["bet",15,"betain: hücre ozmotik koruması","B"],["cr",10,"krom: glikoz kullanımı","B"]],time:"3–7 gün.",besi:[["kco3",60,"K","A"],["bik",100,"tampon","A"],["yeast",15,"maya","A"]],koyun:[["bik",15,"tampon","A"],["kco3",10,"K","B"]]},
 {k:"ishal",n:"İshal / mikotoksin şüphesi (yetişkin)",a:["sut","besi","koyun"],why:"Yetişkin ruminantta ishalin yem kaynakları: asidoz (sulu-köpüklü), fazla protein/üre, bozuk veya küflü yem (mikotoksin: aflatoksin, DON, zearalenon), ani yem değişikliği, kum. Mikotoksin ayrıca süt düşüşü, döl sorunu, aflatoksin M1 (sütte) yapar.",sign:"Sürüde yaygın sulu dışkı, tüketim düşüşü, dışkıda kan/mukus; yemde küf, ısınmış silaj; zearalenon: düvede vulva şişmesi.",chk:"Silaj yüzeyi ve küflü kısımlar atılmalı; nişasta ve HP kontrolü; su kalitesi.",items:[["tox",80,"toksin bağlayıcı (bentonit/HSCAS + maya hücre duvarı): aflatoksin için kil, DON/ZEA için enzim-maya ürünleri","B"],["yeast",20,"maya: rumen stabilizasyonu","A"],["prob",10,"probiyotik","B"]],time:"3–10 gün; küflü yem kesilmeden katkı yetmez.",koyun:[["tox",10,"toksin bağlayıcı","B"],["yeast",3,"maya","A"]]},
 {k:"istah",n:"Yem tüketimi düşük / iştahsızlık",a:["sut","besi","koyun"],why:"Yem alımını düşürenler: sulu veya ısınmış TMR, küf, tuz eksikliği, sıcak, asidoz, ketozis, ayak ağrısı, yemlik alanı ve su yetersizliği, ani yem değişimi.",sign:"Yemlikte artık, geviş azlığı, süt/artış düşüşü, hayvanların yemliğe gelmemesi.",chk:"Rasyon KM %45–55, Na %0,25–0,3 (tuz), yemlik 60 cm/baş, su 10 cm/baş, TMR sıcaklığı.",items:[["salt",80,"tuz: iştah ve su","A"],["yeast",20,"maya: KM alımı +0,5–1 kg","A"],["nia",6,"B vitamini desteği","B"],["bik",150,"asidoz şüphesinde","A"]],time:"3–7 gün.",besi:[["salt",30,"tuz","A"],["yeast",15,"maya","A"]],koyun:[["salt",8,"tuz","A"],["yeast",3,"maya","A"]]},
 {k:"mun",n:"Süt üresi (MUN) yüksek / amonyak kokusu",a:["sut"],why:"Rumende çözünen protein (RDP) mikropların kullanabileceğinden fazlaysa amonyak emilir, karaciğerde üreye çevrilir: enerji kaybı, döl tutmama (embriyo ölümü), ayak sağlığı. Kaynak: fazla küspe/üre/yonca, az enerji.",sign:"MUN > 16–18 mg/dl, ahırda amonyak kokusu, dışkı yumuşak ve koyu.",chk:"HP %16–17, RDP ihtiyacın %100–105'i, nişasta %24–26 (enerji ile dengele).",items:[["yucca",2,"yucca: rumen amonyağını bağlar","B"],["yeast",20,"mikrobiyal protein artışı (azotu kullanır)","B"]],time:"1–2 hafta; asıl çözüm küspe/üre azaltmak."},
 {k:"tetani",n:"Çayır tetanisi (ilkbahar merası)",a:["sut","besi","koyun"],why:"Taze, hızlı büyüyen, azot-potasyum gübreli çayırda Mg düşük ve K yüksektir; Mg emilimi çöker. Kan Mg düşünce kas-sinir sistemi boşalır: titreme, düşme, ölüm.",sign:"Mera çıkışından 1–3 hafta sonra sinirlilik, sendeleme, kasılma, ani ölüm; en çok sağmal inek ve emziren koyun.",chk:"Mera döneminde Mg %0,3–0,35; K < %2,5; mera çıkışını kademeli yapın (ilk gün 2 saat).",items:[["mgo",60,"60 g MgO (30 g Mg) mera döneminde her gün; lezzet için melas/kesif yemle","A"],["salt",50,"tuz: Mg emilimine yardım","B"]],time:"Koruyucu: mera çıkışından 2 hafta önce başlayın.",koyun:[["mgo",7,"7 g MgO","A"],["salt",8,"tuz","B"]]},
 {k:"pem",n:"PEM (beyin yumuşaması) / kükürt zehirlenmesi",a:["sut","besi","koyun"],why:"Rumende yüksek kükürt (DDGS, melas, mısır gluteni, sülfatlı su) H₂S üretir; tiamin (B1) yıkımı ile beyinde polioensefalomalasi. Ani tahıl artışı da tiamini düşürür.",sign:"Körlük, baş basma, dönme, dişleri gıcırdatma, yatma; genç besi hayvanı ve kuzuda sık.",chk:"Toplam S < %0,4 (su dahil); DDGS payını azaltın; tahıl geçişi kademeli.",items:[["tia",500,"tiamin: 500 mg/gün yem katkısı (koruyucu); hasta hayvana enjeksiyon — veteriner","B"],["tox",50,"bentonit","C"]],time:"Koruyucu; hasta hayvan acil veteriner.",koyun:[["tia",100,"100 mg","B"]]},
 {k:"meme",n:"Meme ödemi (düve/doğum öncesi)",a:["sut"],why:"Doğum öncesi fazla tuz ve potasyum, yüksek enerji (yağlı düve) ve hareketsizlik memede sıvı birikimi yapar.",sign:"Doğumdan önce memede sert şişlik, meme bağı gerginliği; sağımda zorlanma.",chk:"Close-up Na < %0,15 (tuz yok), K < %1,3; düvede enerjiyi sınırlı tutun.",items:[["vitE",2,"1.000 IU E + Se (antioksidan)","B"]],time:"Sonraki doğumda; mevcut ödemde veteriner (diüretik)."},
 {k:"sisme",n:"Şişme (timpani)",a:["besi","sut","koyun"],why:"Taze yonca/üçgül merası ve ince öğütülmüş tahıl rumende köpük oluşturur; gaz çıkamaz.",sign:"Sol karın şişkin, solunum güçlüğü, ani ölüm; sürüde yemden 1–3 saat sonra.",chk:"Kaba yem önde, tahıl kaba kırılmış, mera geçişi kademeli ve tok karınla.",items:[["polox",15,"poloksalen: köpük kırıcı (mera şişmesi), riskli dönemde her gün","A"],["mon",300,"iyonofor: yem şişmesini azaltır (reçeteli)","A"],["bik",100,"tampon","B"]],time:"Koruyucu; akut şişme acil (sonda/trokar).",koyun:[["polox",2,"2 g","A"]]},
 {k:"idrar",n:"İdrar taşı (erkek besi / toklu / kuzu)",a:["besi","koyun"],why:"Yüksek fosfor-düşük kalsiyum (tahıl, kepek), az su ve alkali idrar fosfat taşı yapar; erkeklerde idrar yolu dar.",sign:"Sık işeme çabası, kuyruk sallama, karın şişliği (idrar kesesi yırtılması), ölüm.",chk:"Ca:P ≥ 2:1, P < %0,4, tuz %1 (su içsin), kepek/DDGS sınırlı; su her zaman önde.",items:[["nh4cl",25,"amonyum klorür %0,5–1 (idrarı asitleştirir); kuzuda 10 g","A"],["salt",30,"tuz: su tüketimi ve idrar hacmi","A"]],time:"Koruyucu; tıkanmış hayvan acil veteriner.",koyun:[["nh4cl",10,"10 g (toklu)","A"],["salt",10,"tuz","A"]]},
 {k:"apse",n:"Besi: karaciğer apsesi / düşük günlük artış",a:["besi"],why:"Yoğun tahıl beslemede rumen duvarı zedelenir, bakteriler karaciğere gider (apse); yem dönüşümü düşer. İyonofor ve lif yönetimi rumeni korur.",sign:"Kesimde karaciğer ıskartası, sürüde düzensiz artış, asidoz belirtileri.",chk:"Kaba yem en az %10–15, nişasta ≤ %40, tahıl kaba kırılmış.",items:[["mon",300,"iyonofor: yem dönüşümü +%5–8, asidoz azalır (reçeteli)","A"],["yeast",15,"maya","A"],["bik",120,"tampon","A"],["znorg",2,"200 mg Zn: ayak ve bağışıklık","B"]],time:"Besi boyunca."},
 {k:"bakir",n:"Koyun: bakır zehirlenmesi şüphesi",a:["koyun"],why:"Koyun bakırı atamaz; sığır yemi, sığır premiksi veya bakır sülfatlı mineral haftalarca karaciğerde birikir, stresle hemoliz krizi başlar.",sign:"Sarılık, koyu kahverengi idrar, halsizlik, ani ölüm (kırkım, nakil, kuzulama sonrası).",chk:"Rasyon Cu < 10 mg/kg, Mo 1–2 mg/kg, S %0,2; sığır yemi kesilmeli.",items:[["mo",50,"molibden (amonyum molibdat) + kükürt: bakır emilimini keser — veteriner denetiminde","B"],["vitE",0.4,"200 IU E: antioksidan","C"]],time:"Acil veteriner; koruyucu olarak koyun premiksi."},
 {k:"beyazkas",n:"Koyun/buzağı: beyaz kas hastalığı, zayıf yavru",a:["koyun","buzagi","sut"],why:"Selenyum ve E vitamini eksikliği yavrunun iskelet ve kalp kasını bozar; anne gebelikte alamazsa yavru doğumda zayıf, ayağa kalkamaz, emmez.",sign:"Kuzu/buzağıda sertlik, ayağa kalkamama, ani ölüm (kalp); annede retensiyo.",chk:"Anne rasyonunda Se 0,3 mg/kg, E vitamini gebeliğin son 6 haftasında yüksek.",items:[["seorg",3,"6 mg Se (inek)","A"],["vitE",4,"2.000 IU E (inek)","A"]],koyun:[["seorg",0.15,"0,3 mg Se (koyun; toplam rasyon ≤ 0,5 mg/kg KM)","A"],["vitE",0.6,"300 IU E (koyun)","A"]],buzagi:[["seorg",0.25,"0,5 mg Se (buzağı)","A"],["vitE",0.3,"150 IU E","A"]],time:"Doğumdan 6 hafta önce başlayın; yavruya doğumda Se+E enjeksiyonu (veteriner)."},
 {k:"buzishal",n:"Buzağı ishali",a:["buzagi"],why:"İlk 3 haftada E. coli, rota/korona virüs, kriptosporidium; beslemeden gelen nedenler: soğuk/düzensiz süt, kirli kova, fazla süt tek öğünde, kötü ikame. Ölüm nedeni su ve elektrolit kaybıdır.",sign:"Sulu dışkı, çökük göz, deri elastikiyeti azalmış, emmeme.",chk:"Kolostrum ilk 2 saatte 3–4 L; süt sıcaklığı 38–39 °C; öğünler eşit; su serbest; starter taze.",items:[["elec",50,"oral elektrolit: 2 L suda, günde 2 kez, süt öğünleri arasında (sütü kesmeyin)","A"],["prob",5,"probiyotik süte: 5 g","B"],["vitE",0.2,"100 IU E + Se (bağışıklık)","B"]],time:"Elektrolit anında; probiyotik koruyucu."},
 {k:"buzpnomo",n:"Buzağı: solunum hastalığı / zayıf bağışıklık",a:["buzagi"],why:"Kalabalık, nemli, amonyaklı barınak + kolostrum yetersizliği + A/E vitamini ve Se eksikliği.",sign:"Öksürük, burun akıntısı, ateş, hızlı solunum; büyüme duraklaması.",chk:"Kolostrum, havalandırma, kuru yatak; starter'da A 10.000 IU/kg, E 50 IU/kg, Se 0,3 mg/kg.",items:[["vitA",0.03,"30.000 IU A","A"],["vitE",0.3,"150 IU E","A"],["seorg",0.3,"0,6 mg Se","A"],["prob",5,"probiyotik","B"]],time:"2–4 hafta."},
 {k:"yapagi",n:"Tüy/yapağı kalitesi, deri sorunları",a:["sut","besi","koyun"],why:"Keratin sentezi çinko, bakır, iyot, biotin ve kükürtlü amino asitlere bağlıdır; eksikliğinde kaba-mat tüy, deri kalınlaşması (parakeratoz), yapağı kırılganlığı.",sign:"Mat, kırmızımsı tüy, göz çevresi açık tüy (Cu), kalın pul pul deri (Zn), yapağı kopması (koyun: S/Zn).",chk:"Zn 60, Cu 12–15 (koyun 5–10), I 0,5 mg/kg, S %0,2 (koyun yapağı için %0,25).",items:[["znorg",4,"400 mg Zn","A"],["biotin",0.5,"10 mg biotin","B"],["iod",1,"10 mg I","B"],["cu",0.5,"125 mg Cu (koyunda vermeyin)","B"]],time:"6–10 hafta.",koyun:[["znorg",1,"100 mg Zn","A"],["iod",0.3,"3 mg I","B"],["met",3,"korunmuş metiyonin: yapağı büyümesi","B"]]}
];
var MKX={"tirnak": {"why": "Topallığın üç kaynağı vardır. (1) Rumen asidozu → laminitis: hızlı nişasta ve az etkili lif rumen pH'ını düşürür; rumende ölen bakterilerden çıkan endotoksin ve histamin tırnak içindeki kılcal damarları bozar, tırnağı taşıyan bağ dokusu gevşer, tırnak kemiği (P3) tabana çöker → sole ülseri ve beyaz çizgi ayrılması 6–8 hafta sonra ortaya çıkar. (2) Tırnak boynuzunu yapan besinler: biotin keratin arası 'çimento'yu, çinko keratin proteinini, bakır keratin bağlarını (disülfit) ve iyot tiroit yoluyla boynuz büyümesini sağlar; eksikliğinde tırnak yumuşak, çatlak ve geç büyür. (3) Çevre: ıslak-dışkılı zemin boynuzu yumuşatır, dermatitis (topuk siğili) ve ayak çürüğü bakterileri yerleşir; beton ve uzun ayakta kalma mekanik yük bindirir.", "eff": "Topal inek 1–2 saat daha az yer, daha az yatar: süt −2 ila −5 kg/gün, döl tutma −%20–30, erken ayıklama riski 2–3 kat; buzağılama aralığı uzar. Bir sole ülserinin sürüye maliyeti (tedavi + süt + döl) yaklaşık bir inek-ayı süt gelirine denktir. Beside günlük artış düşer, karkas kalitesi bozulur.", "sign": "Hareket puanlaması: yürürken sırt kamburu, kısa adım, baş sallama, ayağı yere koymaktan kaçınma (puan 3–5 topal). Sürüde topal oranı > %10 sorun, > %20 acil. Ayak bakımında: sole kanaması (asidoz izi), sole ülseri, beyaz çizgi ayrılması, çift taban; topuklarda çilek görünümlü kızarık siğil (dijital dermatitis); parmak arası şişlik ve koku (ayak çürüğü). Tırnak yumuşak, çatlak, yavaş büyüyorsa biotin/çinko şüphesi. Dışkı sulu ve geviş azsa SARA şüphesi.", "mgmt": "Ayak banyosu (bakır sülfat %5 veya formalin %3–5, haftada 2–3 gün), 6 ayda bir koruyucu tırnak kesimi, kuru ve yumuşak yatak, zemin temizliği (kazıyıcı), yemlik başında ayakta kalma süresini azaltma (sağım bekleme < 1 saat), topal hayvanı hemen ayırıp tedavi.", "info": "Tırnak boynuzu ayda ~5 mm büyür; tabanın yenilenmesi 2 ay sürer. Bu yüzden bugünkü topallık 6–8 hafta önceki asidozun, bugün verilen biotin ise 3–6 ay sonraki tırnağın işidir. Biotin 20 mg/gün: Hollanda ve İngiltere çalışmalarında beyaz çizgi hastalığı −%50 ve süt +1,2 kg; organik çinko (Zn-metiyonin) dijital dermatitis ve sole ülserini azaltır (Zinpro 40, Hutjens fayda:maliyet 14:1). İnorganik (sülfat/oksit) çinko da işe yarar ama emilimi düşük; yüksek kalsiyum ve demir çinkoyu bağlar."}, "sutyag": {"why": "Süt yağının yarısı memede yeniden yapılır (de novo): ham maddesi rumende lif sindiriminden çıkan asetat ve bütirattır. Diğer yarısı yemden ve vücut yağından gelen uzun zincirli yağ asitleridir. Süt yağı depresyonunun asıl mekanizması 'biyohidrojenasyon kayması': rumen pH düşükken ve doymamış yağ (DDGS, ayçiçeği, pamuk tohumu, soya yağı) fazlayken rumen bakterileri bu yağları normal yol yerine trans-10, cis-12 CLA'ya çevirir; bu molekül memede yağ sentez genlerini kapatır. Çok az miktarı (günde 2–3 g) bile süt yağını %25 düşürür.", "eff": "Süt yağı 3,8'den 3,3'e düşen 30 kg'lık inek günde 150 g yağ = yaklaşık 1,5 kg eşdeğer süt kaybeder; süt fabrikası yağ primi düşer. Aynı rumen koşulu asidoz, topallık ve döl sorunlarını da getirir — süt yağı rumenin 'termometresi'dir.", "sign": "Tank sütü yağı ırk ortalamasının altında (Holstein < %3,5, Simmental < %3,8), yağ:protein oranı < 1,0 (sağlıklı 1,1–1,3); erken laktasyonda tersine > 1,4 ise ketozis. Dışkı sulu ve içinde tane; sürüde yatanların yarısından azı geviş getiriyor (sağlıklı > %60); TMR'de yem seçme (yemlikte iri parçalar kalır). Elek testi: üst elek < %6 ise etkili lif az.", "mgmt": "TMR kıyım boyu 4–5 cm (çok kıyılmış silaj etkili lifi öldürür), günde 2 kez taze yem, yem itme 6–8 kez/gün, yemlik boş kalmasın (yemsiz saatlerden sonra hayvan hızlı yer ve pH çöker), tahılı ince öğütmeyin, yağlı yan ürünleri (DDGS) %10'un altında tutun, sıcakta serin saatte yemleyin.", "info": "Tamponlar nasıl çalışır: sodyum bikarbonat rumen asidini nötralize eder (%0,75 KM, 150–250 g/inek), magnezyum oksit ise alkalileştirici olarak daha yavaş ama uzun etkilidir; birlikte 2–3:1 oranı klasik reçetedir. Canlı maya (Saccharomyces cerevisiae) oksijeni tüketip laktik asit kullanan bakterileri (Megasphaera) besler; süt yağı +0,1–0,2 puan. Kalsiyum sabunu (bypass) yağ rumende parçalanmadığı için biyohidrojenasyona girmez ve memeye doğrudan yağ asidi verir."}, "sutpro": {"why": "Süt proteini (kazein) memede amino asitlerden yapılır; meme kana ne kadar amino asit ve glikoz geliyorsa o kadar üretir. Üç darboğaz: (1) Enerji: rumende propiyonat → karaciğerde glikoz → meme; nişasta düşükse süt proteini düşer, ham protein ne olursa olsun. (2) Metabolik protein: mikrobiyal protein (enerjiye bağlı) + bypass protein. (3) Amino asit dengesi: lizin ve metiyonin 'ilk sınırlayan'dır; biri eksikse diğerleri kullanılamaz ve üre olarak atılır (varil teorisi: en kısa tahta).", "eff": "Süt proteini %3,3'ten %3,0'a düşen 30 kg'lık inek günde 90 g protein kaybeder; protein primi ve peynir verimi düşer. Protein düşük + MUN yüksek ise protein yeme boşa gidiyor demektir (en pahalı besin). Erken laktasyonda süt proteini düşüklüğü, ineğin kas eritmesinin de işaretidir.", "sign": "Tank süt proteini < %3,1 (Holstein) / < %3,3 (Simmental, Jersey > 3,6). MUN ile birlikte okuyun: protein düşük + MUN yüksek → enerji eksik; protein düşük + MUN düşük → protein/amino asit eksik. Kondisyon kaybı > 0,5 puan; dışkı lifli ve hacimli (nişasta az).", "mgmt": "Nişastayı kademeli artırın (haftada +1 kg tahıl), mısır silajı kalitesi (tane kırılmış mı?), yem itme ve taze yem; sıcak stresinde protein önce düşer.", "info": "Lizin:metiyonin oranı 3:1 hedeflenir (MP'nin %7,0 ve %2,4'ü). Soya küspesi lizince zengin, metiyonince fakir; mısır gluteni tersi. Korunmuş metiyonin (Smartamine, Mepron, MetaSmart) 10–25 g/gün süt proteinini +0,1–0,15 puan artırır; meta-analizlerde süt +0,5–1 kg. Rumen korumalı ürünlerde 'emilen metiyonin' etikette yazar; doz ona göre ayarlanır."}, "dol": {"why": "Gebelik dört ayağa basar. (1) Enerji dengesi: doğum sonrası enerji açığı ne kadar derin ve uzunsa ilk ovulasyon o kadar gecikir, yumurta kalitesi düşer; kondisyon kaybı > 1 puan olan ineklerde gebelik oranı yarıya iner. (2) Mineral-vitamin: selenyum ve E vitamini yumurtalık ve uterus savunması, β-karoten/A vitamini korpus luteum ve progesteron, mangan ovulasyon ve embriyo tutunması, bakır-çinko-iyot hormon sentezi; iyot eksikliği tiroiti yavaşlatır ve kızgınlık siliklik yapar. (3) Protein fazlası: MUN > 16 mg/dl uterus sıvısının pH'ını değiştirir, embriyo 7–16. günde ölür ('tekrar kızgınlık'). (4) Sağlık: metritis, retensiyo, topallık, sıcak stresi (yaz aylarında gebelik %50 düşer).", "eff": "Her açık gün (gebelik gecikmesi) ineğe 3–5 € / 100–150 TL'ye mal olur: daha az süt, daha az buzağı, daha çok tohum, daha erken ayıklama. Buzağılama aralığı 13 aydan 15 aya çıkan 100 başlık sürü yılda ~15 buzağı ve 1 laktasyonluk süt kaybeder.", "sign": "İlk tohumlamada gebelik < %40 (hedef > 45–50), gebelik için tohum sayısı > 2,5, buzağılama aralığı > 400 gün, doğum–ilk tohum > 90 gün. 21–25. günde tekrar kızgınlık → embriyo ölümü (MUN, sıcak, enfeksiyon); 35–60. günde tekrar → geç embriyo ölümü (enfeksiyon, mikotoksin). Kistik yumurtalık (sürekli kızgınlık) → enerji ve β-karoten. Kan/süt MUN ölçtürün; kondisyonu doğum, 30. ve 60. günde puanlayın; akıntı kontrolü (metritis).", "mgmt": "Kızgınlık takibi (günde 3 × 20 dk gözlem veya pedometre/aktivite), tohumlama zamanı (AM/PM kuralı), uterus kontrolü 30. günde, topal ineklerde tohumlamayı erteleyin, yazın gölge-fan-duş, sabit sürü grupları (stres), senkronizasyon protokolleri için veteriner.", "info": "β-karoten: A vitamininin ön maddesi ama yumurtalıkta kendi başına rol oynar (korpus luteumun sarı rengi β-karotendir). Yeşil yem ve iyi silajda bol, samanda ve 6 aydan eski silajda azdır; kış sonu en düşük. 300–600 mg/gün takviyesi kistik yumurtalık ve sessiz kızgınlığı azaltır (Alman çalışmaları). Organik selenyum (selenyum mayası) sütle ve embriyoya daha iyi geçer. Omega-3 (keten, balık yağı) prostaglandin F2α'yı baskılayarak embriyonun 'tutunma' sinyalini güçlendirir: tohumlamadan 3 hafta önce başlayıp 3 hafta sonrasına kadar verilir. Krom insülin duyarlılığını artırır ve enerji dengesini iyileştirir."}, "kizg": {"why": "Sessiz kızgınlık iki ayrı şeydir: (a) yumurtalık çalışmıyor (anöstrus): doğum sonrası negatif enerji dengesinde beyin üreme hormonlarını (GnRH/LH) kapatır — inek önce kendini kurtarır, sonra üremeyi açar; kondisyon kaybı derinse ilk ovulasyon 60. günden sonraya kayar. Fosfor, β-karoten, mangan, bakır ve iyot eksikliği de hormon sentezini sınırlar. (b) Yumurtalık çalışıyor ama inek belirti göstermiyor: topallık (atlamaya çekinir), kaygan beton, kalabalık, sıcak, kısa gözlem süresi; Holstein'da kızgınlık süresi 8 saate kadar kısalmıştır ve çoğu gece olur.", "eff": "Gözden kaçan her kızgınlık 21 gün gecikmedir (~2.000–3.000 TL/inek). Anöstrus uzayan inekte buzağılama aralığı 14–15 aya çıkar, laktasyon sonu verimsiz günler artar.", "sign": "Doğumdan 50–60 gün sonra hâlâ kızgınlık görülmemiş; rektal muayenede küçük sert yumurtalık (inaktif) ya da büyük içi sıvı dolu (kist); kondisyon 2,5'in altı veya doğumdan beri > 0,75 puan kayıp; topallık; süt progesteron testi (düşük = ovulasyon yok). Kızgınlık gözlemi günde 3 kez 20 dk, özellikle gece-sabah erken; sürüde 21 günlük kızgınlık tespit oranı < %50 ise gözlem sorunu.", "mgmt": "Aktivite sensörü/pedometre veya kuyruk boyası, gözlem saatlerini artırın, yürüme alanlarında kum/kauçuk zemin, topal inekleri tedavi edin, 45. günden sonra hâlâ kızgınlık yoksa veteriner muayenesi ve gerekirse hormon protokolü (Ovsynch/PRID).", "info": "Fosfor en sık ihmal edilen üreme mineralidir: rasyonda %0,35'in altındaysa kızgınlık silikleşir; ama fazlası (> %0,45) faydasızdır ve çevre kirletir. Mangan ovulasyon için gereklidir, mısır ağırlıklı rasyonda düşüktür (hedef 40–50 mg/kg). İyot tiroit hormonunu, tiroit de yumurtalık ritmini kurar; Türkiye'nin iç bölgeleri iyot fakiridir (hedef 0,5 mg/kg). Korunmuş kolin erken laktasyonda enerji dengesini iyileştirerek dolaylı olarak kızgınlığı erkene çeker."}, "asidoz": {"why": "Rumen pH'ı 6,0–6,8 arasında sağlıklıdır. Hızlı çözünen nişasta (arpa, buğday, ince öğütülmüş mısır, ekmek) ve şeker (melas) rumende saatler içinde laktik ve uçucu yağ asitlerine döner; tükürük (günde 150–200 L, bikarbonatlı) bunu tamponlar ama tükürük geviş getirmeye, geviş de uzun lifli kaba yeme bağlıdır. Kaba yem az, kıyım kısa, tahıl ani artmış veya hayvan uzun açlıktan sonra hızlı yemişse pH 5,5'in altına iner (SARA, günde > 3 saat), 5,0'ın altında akut asidoz (laktik asit birikimi, dehidrasyon, ölüm). Düşük pH'ta lif sindiren bakteriler ölür, rumen duvarı zedelenir (ruminitis), endotoksin kana karışır (laminitis, karaciğer apsesi), protozoalar kaybolur.", "eff": "SARA'lı inekte KM alımı dalgalanır (−%10), süt yağı düşer, 6–8 hafta sonra topallık, kronik ishal, abomazum kayması riski; beside karaciğer apsesi (%20–30 karaciğer ıskartası) ve ani ölümler, yem dönüşümünde −%5–10. Sürü çapında maliyet inek başına yılda yüzlerce lira.", "sign": "Dışkı: sulu, köpüklü (gaz kabarcıklı), parlak-mukuslu, içinde sindirilmemiş tane; dışkı puanı sürü içinde çok değişken (bazı inek 2, bazı 4). Geviş: dinlenen hayvanların < %50'si geviş getiriyor (sağlıklı > %60); geviş süresi < 400 dk/gün. Davranış: yem seçme (yemlikte uzun parçalar kalır), yemlikten uzun süre uzak durma sonra hızlı yeme, kum/toprak yeme, burun ucu kuru. Süt: yağ düşük, yağ:protein < 1,0. Kesin tanı: rumenosentez (12 inekte pH ölçümü, > 3'ü < 5,5 ise sürü SARA) — veteriner.", "mgmt": "Tahıl geçişini 2–3 haftaya yayın (haftada +0,5–1 kg), kaba yem oranı sağmalda ≥ %40 KM, kıyım 4–5 cm, TMR'de ayrışmayı önleyin (su ekleyin, KM %45–55), yemlik 23 saat dolu, 6–8 kez yem itme, beside kaba yem en az %10–15 ve serbest saman erişimi, ani yem değişikliği yok, uzun açlıktan (sağım, nakil) sonra önce kaba yem verin.", "info": "Tahıl türü farkı: buğday ve arpa nişastasının %80–90'ı rumende 6 saatte çözünür, mısırın %50–60'ı; bu yüzden aynı nişasta yüzdesinde arpa daha risklidir. Öğütme inceliği çözünmeyi hızlandırır: mısırı kaba kırın (2–4 mm), flake ise 'hızlı' sayılır. İyonofor (monensin) laktik asit üreten gram-pozitif bakterileri baskılayıp propiyonat üretenleri korur; AB'de süt ineğinde yasaklı, Türkiye'de reçeteli. Canlı maya, Megasphaera elsdenii gibi laktat kullanan bakterileri uyarır; etkisi tamponlarla birlikte en iyidir."}, "ketoz": {"why": "Doğumdan 3 hafta önce başlayan iştah düşüşü ve doğumdan sonra sütün aniden başlaması enerji açığını (günde 5–10 Mcal) yaratır; inek bunu vücut yağını (NEFA) kana vererek kapatır. Karaciğer bu yağın bir kısmını yakar, bir kısmını VLDL olarak süte yollar, kalanı içinde depolar (yağlı karaciğer). Karaciğer glikoz üretmeye yetişemezse (propiyonat azsa) yağ tam yanmaz ve keton cisimleri (BHB, aseton) birikir: ketozis. Yağlı inek (kondisyon > 3,75) daha az yer ve daha çok yağ eritir: en riskli gruptur. Koyunda ikiz gebelikte son 6 haftada aynı mekanizma gebelik toksemisidir.", "eff": "Subklinik ketozis (BHB 1,2–3,0 mmol/L) sürüde %20–40 görülür ve klinik olandan daha pahalıdır: süt −2 ila −4 kg/gün, abomazum kayması riski 3–8 kat, metritis 2 kat, döl tutma gecikmesi, ayıklama; vaka başına kayıp birkaç bin TL. Klinik ketozis iştahsızlık ve süt çöküşüyle 1–2 hafta sürer, tedavi gerektirir. Yağlı karaciğer bağışıklığı çökertir (metritis, mastitis).", "sign": "Doğum sonrası 5–50. günlerde: önce kesif yemi bırakıp kaba yeme yönelme, hızlı zayıflama (haftada > 0,25 kondisyon puanı), süt yağı:protein > 1,4, nefes/sütte aseton (tatlı) kokusu, dışkı kuru ve az, sinirsel form (yalama, körlük, sendeleme). Sürü taraması: doğum sonrası 3–14. günlerde 12 inekte kan BHB ölçümü (el cihazı); > %15'i ≥ 1,2 mmol/L ise sürü sorunu. İdrar/süt keton stripleri ucuz tarama. Koyunda gebelik son 4 haftasında iştahsızlık, sürüden ayrılma, diş gıcırdatma, körlük, yatış.", "mgmt": "Kuru dönem kondisyonu 3,0–3,5'te sabit tutun (ne yağlandırın ne zayıflatın), close-up grubunda yemlik alanı 75 cm/baş ve KM alımı ≥ 12 kg, doğum sonrası taze yem ve su, kalabalık yok (< %100 doluluk), doğum sonrası ilk 2 hafta günlük iştah kontrolü, riskli ineklere (yağlı, ikiz, zor doğum) koruyucu propilen glikol.", "info": "Korunmuş kolin (ReaShure, CholiPEARL): kolin rumende parçalandığından mutlaka korumalı olmalı; 15 g kolin = 60 g %25'lik ürün; doğumdan 3 hafta önce başlayıp 6 hafta sonrasına kadar; meta-analiz (JDS 2025): süt +1,5–2 kg, yağlı karaciğer −%30. Propilen glikol karaciğerde glikoza döner: 300 ml tek seferde ağızdan verilmeli (TMR'ye karışınca etkisi azalır). Niasin yağ dokusundan yağ salınımını frenler; korunmasız 12 g'ın çoğu rumende kaybolur, korunmuş 3–6 g yeter. Monensin propiyonat üretimini artırır, ketozisi %25–50 azaltır (reçeteli). Krom insülinin etkisini artırır, erken laktasyonda KM alımı +1 kg."}, "humma": {"why": "Doğumda kolostrumla günde 20–30 g kalsiyum kaybolur; kan Ca havuzu (yalnızca 3 g) saatler içinde boşalır. İnek bunu bağırsak emilimini ve kemikten Ca çözmeyi artırarak kapatmalıdır; bu sistem paratiroit hormonu (PTH) ve D vitamini ile çalışır. Kuru dönemde yüksek potasyum (ve sodyum) kanı hafif alkali yapar, alkali ortamda dokular PTH'ye sağır olur: 'uyuyan sistem'. Anyonik tuzlar (klor, kükürt) kanı hafif asitleştirir ve sistemi uyandırır. Yüksek Ca'lı kuru dönem rasyonu da sistemi tembelleştirir (ya çok düşük Ca < %0,5 ya da anyonik programla yüksek Ca). Magnezyum PTH'nin hem salınımı hem etkisi için şarttır. Yaşlı inekte (3+ doğum) bağırsak ve kemik reseptörleri azaldığından risk artar.", "eff": "Klinik süt humması (%2–8) inek başına tedavi + süt kaybı + ikincil hastalıklar (retensiyo ×4, abomazum kayması ×3, ketozis ×2, mastitis ×8, uterus prolapsusu); ölüm riski %5. Subklinik hipokalsemi (kan Ca < 2,0 mmol/L, belirti yok) çok daha yaygındır (%25–50) ve kas tonusunu düşürerek yem alımı, rumen hareketi ve uterus involüsyonunu bozar — doğum sonrası hastalıkların görünmeyen kökü.", "sign": "Evre 1 (ayakta): huzursuzluk, kas titremesi, sallantı, kulaklar soğuk, burun kuru. Evre 2: göğüs üstü yatış, baş yana kıvrık (S boyun), dışkılama durur, şişme. Evre 3: yan yatış, bilinç kaybı. Doğumdan 0–48 saat içinde; Jersey ve yaşlı ineklerde daha sık. Sürü kontrolü: close-up ineklerde idrar pH (anyonik programda 6,0–6,8; > 7,5 ise program çalışmıyor), doğum sonrası 1–2. gün kan Ca (< 2,0 mmol/L subklinik), sürüde klinik vaka > %5 ise rasyon sorunu.", "mgmt": "Close-up (son 3 hafta) ayrı grup ve rasyon, potasyumu düşük kaba yem (saman, mısır silajı; yonca-mera yok), doğum anında yaşlı ineklere Ca bolusu, yatan ineğe damar içi Ca (veteriner), doğumdan sonra bol su ve taze yem.", "info": "DCAD = (Na + K) − (Cl + S) mEq/kg KM. Close-up hedefi −50 ile −150; sağmal +250 ile +450 (sıcak stresinde +350 ile +450). Anyonik tuzlar lezzetsizdir (iştahı düşürürse humma yerine ketozis gelir): kademeli başlayın, melasla karıştırın, hazır ürünler (Bio-Chlor, SoyChlor) daha lezzetli. Alternatif: düşük Ca stratejisi (< %0,5 — pratikte zor) veya zeolit (Ca bağlayıcı, 500 g/gün). D vitamini 25.000 IU/gün destek, ama tek başına yetmez. Doğumdan sonra Ca bolusu (2 × 40–50 g Ca) 3+ doğumlu ineklerde subklinik hipokalsemiyi azaltır; damardan Ca ise kalbi durdurabileceğinden yalnız veteriner."}, "retens": {"why": "Plasenta doğumdan sonra uterusta 'kendi dokusu' muamelesi görmemelidir; bağışıklık hücreleri (nötrofiller) onu yabancı tanıyıp bağlantı noktalarını eritir. Selenyum ve E vitamini bu hücrelerin yangın söndürücüsüdür (antioksidan): eksikliğinde nötrofil güçsüzdür ve plasenta kalır. Hipokalsemi uterus kasılmasını, ketozis ve yağlı karaciğer bağışıklığı zayıflatır. Güç doğum, ikiz, erken doğum, düşük ve enfeksiyonlar (brusella, BVD) de nedendir; iyot eksikliği de bildirilmiştir.", "eff": "Retensiyolu inekte metritis riski %60–80, döl tutma 20–30 gün gecikir, süt −3 ila −5 kg (ilk 2 ay), mastitis ve ketozis artar; ayıklama riski 2 kat. Metritis tedavisi antibiyotik ve süt atımı demektir.", "sign": "Doğumdan 12–24 saat sonra son hâlâ asılı; sürüde > %8 (hedef < 5). Metritis: doğum sonrası 3–10 gün kırmızı-kahverengi kötü kokulu sulu akıntı, ateş > 39,5 °C, iştahsızlık, süt düşüşü. Endometritis (geç): 21 günden sonra irinli akıntı, tohumlamada tutmama. Kan/karaciğer Se düzeyi, E vitamini düzeyi, close-up KM alımı ve kondisyon kontrol edin; retensiyo artışı yem değişikliğinden 3–4 hafta sonra görülürse rasyon bağlantısı düşünün.", "mgmt": "Temiz ve kuru doğum bölmesi, doğuma müdahalede hijyen, doğumu zorlamamak (buzağı pozisyonu düzgünse 2 saat bekleyin), sonu elle çekmeyin (uterus zedelenir), doğum sonrası 3–10 gün ateş takibi, aşılama (BVD, IBR) programı.", "info": "E vitamini close-up dönemde 2.000 IU/gün (NASEM 2021 bu düzeyi NRC 2001'in 3 katına çıkardı), sağmalda 500–1.000 IU. Selenyum yasal üst sınır 0,3–0,5 mg/kg KM; organik Se (selenyum mayası) karaciğerde daha iyi depolanır ve kolostruma geçer (buzağı bağışıklığı). Doğumdan 3 hafta önce Se+E enjeksiyonu (veteriner) rasyon desteğini tamamlar. Türkiye'de birçok bölge toprak selenyumu düşük olduğundan kaba yemler Se fakiridir; yem analizinde Se görmezseniz 'yok' varsayın."}, "mastit": {"why": "Mastitis iki kapıdan girer: çevresel bakteriler (E. coli, Strep. uberis — yatak, dışkı, çamur) ve bulaşıcı bakteriler (Staph. aureus, Strep. agalactiae — sağım makinesi ve eller). Meme savunması meme başı kanalı keratini (çinko), somatik hücrelerin öldürme gücü (Se, E vit, A vit/β-karoten, bakır) ve genel bağışıklıktır. Kuru dönem başlangıcı ve doğum sonrası ilk 2 hafta en riskli dönemdir (bağışıklık baskısı, meme ödemi, kolostrum). Negatif DCAD'lı sağmal rasyon ve hipokalsemi de meme başı sfinkterini gevşetir.", "eff": "Somatik hücre 100.000'den 400.000'e çıkınca süt −%5–8 (inek başına günde 1–2 kg), süt primi düşer, antibiyotik ve atılan süt, erken ayıklama. Klinik vaka başına kayıp birkaç bin TL; kronik Staph. aureus inekleri sürüye bulaştırır.", "sign": "Tank somatik hücre > 300.000 (hedef < 200.000), bireysel CMT testi pozitif inek oranı > %15, aylık klinik vaka > %2, kuru dönem sonrası yeni enfeksiyon > %10. Sütte pıhtı, memede sıcaklık-şişlik-ağrı, E. coli'de ateş ve çökkünlük. Çevresel mi bulaşıcı mı: tank sütü kültürü. Yem bağlantısı: E vitamini ve Se düşük sürülerde klinik mastitis 2 katına çıkar (Weiss, Ohio State); yüksek nemli yatak + düşük Se birlikte ise alarm.", "mgmt": "Sağım rutini (ön daldırma, kuru silme, son daldırma), sağım başlıklarının 6 ayda değişimi ve vakum kontrolü, kuru ve sık değişen yatak (kum en iyisi), kuru dönem meme içi koruma, enfekte ineklerin en son sağılması, kronik ineklerin ayıklanması, sinek kontrolü.", "info": "Somatik hücre esas olarak nötrofildir; Se+E vitamini nötrofilin bakteri öldürme gücünü %30–40 artırır. Çinko (özellikle organik) meme başı kanalındaki keratin tıkacını güçlendirir ve SHS'yi 20–30 bin düşürür (Hutjens fayda:maliyet yüksek). A vitamini ve β-karoten meme epitelini korur; kış sonu samanlı rasyonlarda düşüktür. Bakır nötrofil enzimleri (süperoksit dismutaz) için gereklidir. Katkılar hijyen yoksa SHS'yi düşürmez; birlikte verildiğinde 4–8 haftada etki görülür."}, "sicak": {"why": "Sıcaklık-nem indeksi (THI) 68'i aşınca (24 °C + %50 nem gibi) inek ısı üretmemek için yemi azaltır (−%10–25), gölgede ayakta durur (yatmaz), solur. Soluma ile CO₂ kaybı kanı alkali yapar; böbrek dengelemek için bikarbonat atar → rumen tamponu azalır. Terle potasyum ve sodyum kaybedilir. Yem gün içinde dengesiz yenir (serin saatte aşırı yüklenme → asidoz). Kan akışı deriye kayar, bağırsak ve uterus kanlanması azalır (bağırsak geçirgenliği, embriyo ölümü). Yüksek verimli inek daha fazla ısı üretir ve daha çok etkilenir; kuru dönem sıcak stresi buzağının ve sonraki laktasyonun verimini de düşürür.", "eff": "Süt −%10–25 ve süt yağı/proteini düşer, gebelik oranı yaz aylarında %45'ten %20'ye iner (etkisi sonbahara sarkar), somatik hücre ve mastitis artar, SARA ve topallık sonbaharda patlar, ölüm riski artar. Kuru dönemde sıcak stresi yaşayan ineklerin buzağıları daha hafif doğar, bağışıklığı zayıftır ve kendi verimleri düşüktür.", "sign": "Solunum > 60/dk (sağlıklı 25–40), ağzı açık soluma, salya, ayakta durma süresi artışı, su tüketimi 2 katı, yemlik artığı, geviş azalması, süt düşüşü, rektal sıcaklık > 39,2 °C. THI'yı ölçün (termometre + nem); THI > 72 orta, > 80 ciddi stres. Yem gün içi tüketim dağılımı (gece yeme), dışkı sulanması.", "mgmt": "Gölge (3,5–4 m²/baş), fan + duşlama (yemlik önü ve bekleme alanı), su 10 cm/baş ve serin, yemlemeyi akşam-gece saatlerine kaydırın (%60'ı akşam), taze yem ve yem itme sık, yüksek lifli dolgu yemleri azaltıp enerji yoğunluğunu artırın (yağ, iyi kaba yem), sağım bekleme süresi kısa.", "info": "Potasyum karbonat (K₂CO₃) hem terle kaybedilen potasyumu yerine koyar hem DCAD'ı yükseltir (hedef yazın +350–450 mEq/kg; sodyum bikarbonat da aynı işi görür, ikisini birlikte kullanın). Canlı maya yazın KM alımını +0,5–1 kg ve süt +1 kg artırır. Niasin derideki kan akımını (vazodilatasyon) artırarak ısı atılmasını destekler: korunmasız 12 g ya da korunmuş 3–6 g. Betain hücre ozmotik dengesini korur; kümes hayvanlarından ruminanta uyarlanmış 10–20 g dozları süt verimini korur. Krom glikozun kullanımını iyileştirir. Yağ 'serin' enerjidir: sindirimi daha az ısı üretir (nişasta ve lifin fermantasyonu ısı yayar)."}, "ishal": {"why": "Yetişkin ruminantta sürü çapında ishal çoğu zaman yemden gelir: asidoz (sulu-köpüklü), fazla protein veya üre (yumuşak-koyu), ani yem değişikliği, bozuk-ısınmış silaj, kum/toprak, fazla tuz-mineral, aşırı sulu mera. Mikotoksinler (küf zehirleri) ayrı bir bölümdür: aflatoksin (karaciğer, sütte M1), DON (iştah, ishal, bağışıklık), zearalenon (östrojen taklidi: vulva şişmesi, kist, düşük), T-2 ve fumonisin; mısır silajı, pamuk tohumu, kepek ve ıslanmış tahıllarda bulunur; rumen bazısını parçalar ama yüksek verimli inek daha duyarlıdır. Enfeksiyöz nedenler (BVD, salmonella, paratüberküloz/Johne, parazit) ayırıcı tanıda veterinere aittir.", "eff": "Su ve mineral kaybı, enerji kaybı, süt düşüşü; mikotoksinde döl sorunları, bağışıklık çöküşü (mastitis artışı), aflatoksin M1 nedeniyle süt satış yasağı riski. Kronik ishalde kondisyon kaybı ve ayıklama.", "sign": "Dışkı puanı 1–2 (sulu) sürüde yaygın, köpük ve tane varsa asidoz; kötü koku ve yumuşak-koyu ise protein; kan/mukus varsa enfeksiyon düşünün. Yem kontrolü: silaj yüzeyinde beyaz-mavi-pembe küf, ısınmış (> 10 °C ortamdan sıcak) TMR, küflü balya, nemli depolanmış tahıl; TMR'nin günlük kalanı kokuyor mu? Mikotoksin şüphesi: iştah dalgalanması, düvede vulva şişmesi (zearalenon), süt düşüşü + bağışıklık sorunları birlikte; yem numunesi analizi (aflatoksin, DON, ZEA). Su analizi (nitrat, sülfat, bakteri).", "mgmt": "Silaj yüzeyinin küflü 10–20 cm'ini atın, günlük silaj alım yüzeyini 30 cm ilerletin (ısınma olmasın), TMR'yi günde 2 kez taze yapın, depoda nem < %14, yemlik ve suluk temizliği, ani değişiklik yok (7–10 günde geçiş), parazit programı ve BVD/paratüberküloz taraması (veteriner).", "info": "Toksin bağlayıcılar: kil mineralleri (bentonit, HSCAS) aflatoksini iyi bağlar ama DON ve zearalenonu bağlamaz; bunlar için maya hücre duvarı (glukomannan) ve enzim bazlı 'dönüştürücü' ürünler gerekir — etiketteki toksin listesine bakın. Doz 50–100 g/inek/gün (%0,2–0,5 KM). Bağlayıcı vitaminleri ve iz mineralleri de bağlayabilir; uzun süreli yüksek dozda mineral takviyesini artırın. Maya ve probiyotikler rumen ve bağırsak florasını stabilize eder; antibiyotik değildir, enfeksiyonu tedavi etmez."}, "istah": {"why": "Kuru madde alımı rasyonun temelidir ve 'hayvan neden yemiyor?' sorusunun cevabı genelde yemin kendisindedir: ısınmış/ekşimiş TMR (silaj aerobik bozulma), küf, aşırı sulu (KM < %40) veya aşırı kuru-tozlu rasyon, lezzetsiz katkılar (MgO, anyonik tuz, üre, yağ), tuz eksikliği (sodyum iştah merkezini uyarır), kötü su (sıcak, kirli, az), yemlik alanı ve itme sıklığı, sıcak stresi, asidoz/ketozis gibi hastalıklar, topallık (yemliğe gitmez), gruplama stresi (yeni inek 2–3 gün az yer), B vitamini sentezinin azaldığı rumen bozuklukları.", "eff": "KM alımı 1 kg düşerse süt 2 kg düşer; doğum sonrası düşük alım ketozis-abomazum-metritis zincirini başlatır; beside günlük artış ve yem dönüşümü düşer. İştahsızlık çoğu hastalığın ilk ve en ucuz uyarısıdır.", "sign": "Yemlikte beklenenden fazla artık (hedef %3–5), hayvanların yemliğe toplanmaması, geviş azlığı, süt/artış düşüşü, dışkı az ve sert (az yemiş) veya sulu (asidoz). TMR'yi elinizle kontrol edin: sıcak mı, ekşi/alkol kokuyor mu, ayrışmış mı? KM'yi ölçün (mikrodalga/fırın), suluğu kontrol edin (akış 10 L/dk, sıcaklık, kirlilik), tuz tüketimini ölçün (yalama taşı aşınması yetmez). Belirli inekler mi yoksa sürü mü? Sürüyse yem/su, bireyse hastalık.", "mgmt": "Günde 2 kez taze TMR, 6–8 kez yem itme, yemlik ve suluk günlük temizlik, silaj yüzey yönetimi, yemlik alanı 60–75 cm/baş, su 10 cm/baş, gruplamayı en aza indirin, sıcakta gece yemleme, lezzetsiz katkıları melas/kesif yemle maskeleyin.", "info": "Tuz: sodyum hem iştah hem tükürük tamponu için gerekir; sağmal inek 80–120 g/gün tuz ister. Canlı maya rumen ortamını stabilize ederek KM alımını +0,5–1 kg artırır (özellikle geçiş döneminde). B vitaminleri (niasin, biotin, B12) normalde rumende yapılır; rumen bozulduğunda eksik kalır ve iştahı etkiler. Lezzet artırıcılar (melas, anason-vanilya aromaları) ani değişikliklerde yardımcıdır ama asıl sorun yem kalitesi ise maskeler."}, "mun": {"why": "Rumende çözünen protein (RDP) amonyağa dönüşür; mikroplar bu amonyağı ancak eş zamanlı enerji (nişasta, şeker) varsa proteine çevirebilir. Enerji yoksa amonyak rumen duvarından emilir, karaciğerde üreye döner, kana ve süte geçer (MUN), idrarla atılır. Her gram fazla azot için karaciğer enerji harcar; yüksek üre uterus sıvısını ve embriyoyu bozar, tırnak ve karaciğere yük bindirir. Kaynak: fazla küspe/üre/yonca/taze mera (bahar merası HP %25'e çıkar), düşük nişasta, tahıl-küspenin farklı saatlerde verilmesi (senkronizasyon bozukluğu).", "eff": "MUN 18 mg/dl üstü sürülerde gebelik oranı %20 düşer; protein boşa gider (en pahalı hammadde), azot çevreye atılır, süt proteini artmaz. Çok düşük MUN (< 8) ise protein yetersizliğinin işaretidir.", "sign": "Tank sütü MUN > 16–18 mg/dl (hedef 10–14), ahırda keskin amonyak kokusu, dışkı yumuşak-koyu ve bol, döl tutmama; süt proteini düşük + MUN yüksek → enerji açığı. Rasyonda HP ve RDP hesaplayın, nişastayı ve kaba yem kalitesini kontrol edin; mera döneminde MUN mevsimsel yükselir.", "mgmt": "Küspe/üre miktarını düşürün, nişastayı dengeleyin, TMR'de tahıl ve küspeyi birlikte verin, bahar merasında kuru ot/saman takviyesi, protein kaynaklarını bypass değeri yüksek olanlara (soya ısıl işlemli, mısır gluteni) kaydırın.", "info": "Yucca schidigera ekstraktı (saponin) rumen amonyağını geçici bağlar ve amonyak kokusunu azaltır; etkisi ılımlıdır (Hutjens: değerlendirmede). Asıl düzeltme rasyondadır: RDP ihtiyacın %100–105'i, nişasta %24–26. Üre kullanılıyorsa günde en çok 150 g, tahılla birlikte, 2 haftada kademeli; üre bir anda verilirse amonyak zehirlenmesi (titreme, salya, ölüm) olur."}, "tetani": {"why": "Magnezyum kan düzeyi kemikten hızlı çözülemez; her gün yemden gelmelidir. İlkbahar merası (taze, hızlı büyüyen, azot-potasyum gübreli ot) magnezyumca fakir, potasyum ve proteince zengindir; yüksek K rumende Mg emilimini engeller, yüksek amonyak da Mg'yi bağlar. Emziren/sağmal hayvan süte Mg verir ve açık büyür. Soğuk-yağışlı hava ve açlık (nakil) krizi tetikler. Kan Mg düşünce sinir-kas sistemi kontrolsüz boşalır.", "eff": "Ani ölüm (çoğu zaman ilk belirti ölü hayvandır), sürüde %1–5 kayıp; hafif olgularda süt düşüşü, sinirlilik, süt humması benzeri yatış (Mg eksikliği aynı zamanda süt hummasını tetikler).", "sign": "Mera çıkışından 1–3 hafta içinde: ürkeklik, kulak oynatma, kas seğirmesi, sendeleme, sert yürüyüş, ani düşme ve kasılma, köpüklü ağız; en çok yaşlı sağmal inek ve ikiz emziren koyun. Ölü hayvanda yerde çırpınma izleri. Kan Mg < 0,65 mmol/L; idrar Mg tarama. Mera otunda Mg < %0,2 ve K/(Ca+Mg) oranı > 2,2 ise risk yüksek.", "mgmt": "Mera geçişini kademeli yapın (ilk gün 2 saat, sabah kaba yem vererek), meraya çıkmadan 2 hafta önce Mg takviyesine başlayın, riskli dönemde her gün 60 g MgO (kesif yem veya melaslı yalama ile), soğuk günlerde kaba yem ve barınak, potasyumlu gübreyi mera döneminden sonra uygulayın, Mg'li yalama taşı tek başına yetmez (tüketim düzensiz).", "info": "MgO %54 Mg içerir ama emilimi %20–30 civarındadır; günde 30 g Mg (= 60 g MgO) inek, 3,5 g Mg koyun için koruyucudur. Lezzetsizdir: melas, kesif yem veya su katkısı (magnezyum klorür) ile verilir. Kalsiyum ve fosfor Mg emilimini azaltmaz, potasyum ve amonyak azaltır. Hasta hayvana damar/deri altı Mg (veteriner) saatler içinde hayat kurtarır."}, "pem": {"why": "Tiamin (B1) beynin glikoz kullanımı için gereklidir; normalde rumen bakterileri yeterince üretir. Üç durum bozar: (1) yüksek kükürt (DDGS %0,8–1 S, melas, mısır gluteni, sülfatlı su, kükürtlü gübre kalıntısı): rumende hidrojen sülfür gazı oluşur, geğirmeyle solunur ve beyinde oksidatif hasar yapar, tiamini de yıkar; (2) ani tahıl artışı/asidoz: tiaminaz enzimi üreten bakteriler çoğalır; (3) bazı bitkiler (eğrelti) ve amprolyum. Beyin kabuğunda yumuşama (polioensefalomalasi).", "eff": "Tedavi edilmezse 1–3 günde ölüm; erken yakalanırsa tiamin enjeksiyonuyla çoğu düzelir ama bazıları kör kalır. Besi ve kuzu sürülerinde yüksek DDGS'li rasyonlarda salgın görülebilir.", "sign": "Önce sürüden ayrılma, körlük (engellere çarpma, göz refleksi var ama görmüyor), baş yukarı-yıldız bakışı, baş basma, dönme, diş gıcırdatma, sonra yatış ve kürek çekme hareketi. Genç besi hayvanı ve kuzuda daha sık. Rasyon toplam S (su dahil) > %0,4 ise PEM riski; DDGS > %20, melas > %5, su sülfatı > 500 mg/L kontrol edin. Veteriner tanısı: tiamin yanıtı 6–12 saatte.", "mgmt": "DDGS ve kükürtlü yemleri sınırlayın (toplam S < %0,3–0,4), su analizi (sülfat), tahıl geçişi kademeli, sülfatlı mineral (MgSO₄, CuSO₄) dozlarını kontrol edin, hasta hayvanı hemen ayırıp veteriner.", "info": "Tiamin yem katkısı olarak koruyucu etkisi sınırlıdır (rumende parçalanır); korumalı B vitamin ürünleri veya 500 mg/gün yüksek doz denenir. Kesin tedavi tiamin HCl enjeksiyonu (10 mg/kg, günde 2–3 kez, 3 gün — veteriner). Kükürt zehirlenmesinde ayrıca bakır ve selenyum emilimi de düşer; uzun süreli DDGS kullanımında bakır takviyesi gerekir."}, "meme": {"why": "Doğum öncesi memede kan akımı ve basınç artar; damar dışına sızan sıvı meme ve göbek altında birikir. Yüksek tuz ve potasyum vücutta su tutar; düvelerde aşırı enerji (yağlı düve) ve hareketsizlik, bazı ailelerde kalıtım, E vitamini-selenyum eksikliği (damar geçirgenliği) ve kolostrum birikimi ödemi büyütür.", "eff": "Meme bağı gevşer (sarkık meme, ömür boyu), sağım zorlaşır, meme başı yaralanmaları ve mastitis artar, hayvan ağrıdan yatmaz ve az yer; ağır ödem meme dokusunun bir kısmını kalıcı bozar.", "sign": "Doğumdan 2–3 hafta önce başlayan memede sert-hamursu şişlik (parmak bastırınca çukur kalır), göbek altına yayılma, meme bağı gerginliği; doğumdan sonra 1–2 haftada gerilemeli, gerilemiyorsa kronik. En çok ilk doğumunu yapan yağlı düvelerde. Close-up rasyonunda tuz ve potasyumu, düvelerin kondisyonunu (> 3,75 riskli) kontrol edin.", "mgmt": "Close-up'ta tuz vermeyin (Na < %0,15), potasyum düşük kaba yem, düveleri son 2 ayda aşırı beslemeyin, yürüme alanı/egzersiz, doğum öncesi günde 2 kez kısmi sağım (kolostrumu saklayın) sadece ağır ödemde, veteriner (diüretik, kortikosteroid) ağır olgularda.", "info": "Ödem besleme hastalığı olmaktan çok yönetim hastalığıdır; ama E vitamini (1.000 IU) ve selenyum damar geçirgenliğini azaltır, bazı çalışmalarda ödemi hafifletmiştir. Anyonik tuz programı (klor yüklü) ödemi artırmaz; sodyum klorür (tuz) artırır. Düve close-up rasyonunda enerji 1,4–1,5 Mcal NEL/kg yeter; yağlı düve hem ödem hem güç doğum hem ketozis demektir."}, "sisme": {"why": "Rumen gazı (günde 1.000 L) normalde geğirmeyle atılır. İki tip şişme: (1) köpüklü (mera): taze yonca, üçgül, genç buğdaygil otu ve ince öğütülmüş tahıl rumen sıvısında kararlı köpük yapar, gaz kabarcıklar içinde hapsolur ve geğirilemez; (2) serbest gazlı: yemek borusu tıkanması, yatış, sinir felci, asidozda rumen hareketsizliği. Beside yüksek tahıl + az lif + ince öğütme 'yem şişmesi' yapar (salya azalır, mukus artar).", "eff": "Rumen diyaframa basar, solunum durur: 1–3 saatte ölüm. Besi sürülerinde yem şişmesi kronik verim kaybı ve ani ölümlerle gider; mera şişmesi bir gecede birden fazla hayvan alabilir.", "sign": "Sol karın (açlık çukuru) yükselmiş, davul gibi gergin, vurunca tok ses; huzursuzluk, sık yatıp kalkma, karına tekme, solunum güçlüğü, ağız açık, dil dışarı; sonra yatış ve ölüm. Yemden 1–3 saat sonra görülür. Kronik hafif şişme: sol karında sürekli dolgunluk, iştah dalgalanması. Mera: çiy/yağmur sonrası taze yonca, aç hayvanın meraya salınması; besi: öğütme inceliği, kaba yem oranı < %10, pelet yem.", "mgmt": "Meraya tok karınla (önce kuru ot) ve kademeli çıkarın, yonca merasında çiçeklenme sonrası ve çiy kalktıktan sonra otlatın, saman/kuru ot serbest, tahılı kaba kırın, beside kaba yem ≥ %10–15, pelet yem oranını sınırlayın, riskli dönemde şişme önleyici (poloksalen) içeren yalama/katkı, acil durumda sonda ve trokar (veteriner).", "info": "Poloksalen köpüğü kıran bir yüzey aktif maddedir: mera şişmesine karşı 10–20 g/gün (riskli dönemde her gün, yalama bloğu veya kesif yemle) çok etkilidir; yem şişmesinde zayıf. İyonoforlar (monensin, lasalosid) yem şişmesini %50 azaltır (reçeteli). Bitkisel yağ veya parafin yağı (250–500 ml ağızdan) acil köpük kırıcıdır; dimetikon ürünleri de kullanılır. Kronik şişmede yemek borusu/vagus sorunu için veteriner."}, "idrar": {"why": "Erkek ruminantta idrar yolu uzun, dar ve S kıvrımlıdır; idrarda çözünmüş mineraller kristalleşince tıkanır. Tahıl-kepek ağırlıklı yem fosforca zengin, kalsiyumca fakirdir (Ca:P < 1:1); fazla fosfor idrarla atılır ve alkali idrarda magnezyum-amonyum-fosfat (struvit) taşı yapar. Az su içme (donmuş-kirli su, tuz yok) idrarı yoğunlaştırır. Silisli mera ve yonca-okzalat başka taş tipleri yapar. Erken kastrasyon üretrayı dar bırakır.", "eff": "Tam tıkanmada 24–48 saatte idrar kesesi veya üretra yırtılır (karın şişer, 'su karnı'), hayvan ölür; ameliyat besi hayvanında ekonomik değildir. Kısmi tıkanmada ağrı, iştahsızlık, kilo kaybı. Besi ve toklu sürülerinde %1–5 kayıp sık görülür.", "sign": "Sık sık işeme pozisyonu ama damla damla idrar, kuyruk sallama, karına tekme, huzursuzluk, kıvrılma; prepusyum kıllarında kristal/kum, kan damlası; sonra karın alt kısmında şişlik ve çökkünlük. Rasyon Ca:P oranını hesaplayın (hedef ≥ 2:1), P < %0,4, kepek/DDGS payı, tuz oranı, su tüketimi; idrar pH > 7,5 ise asitleştirme gerekli (hedef 6,0–6,5).", "mgmt": "Rasyonda kireç taşı ile Ca:P ≥ 2:1, tuz %0,5–1 (su içsin), su temiz ve donmamış, kepek-DDGS sınırlı, amonyum klorür koruyucu, kastrasyonu 4–6 aydan önce yapmayın, yonca ve silisli meralarda dikkat; tıkanan hayvan acil veteriner.", "info": "Amonyum klorür idrarı asitleştirir (struvit asit idrarda çözünür): sığırda rasyonun %0,5–1'i (günde 20–45 g), koyun-kuzuda 7–10 g; lezzetsizdir, kesif yeme karıştırılır; uzun süreli yüksek dozda metabolik asidoz ve iştah düşüşü yapar, 2–3 ayda bir ara verilir. Alternatif asitleştirici: anyonik tuzlar, amonyum sülfat. Tuz %1'e çıkarmak su tüketimini artırır, idrarı seyreltir ve tek başına riski yarıya indirir."}, "apse": {"why": "Yoğun tahıl rasyonunda tekrarlayan asidoz rumen duvarını zedeler (ruminitis, parakeratoz); Fusobacterium necrophorum ve Trueperella bu yaralardan kan yoluyla karaciğere gider ve apse yapar. Apse besin emilimini ve karaciğer işlevini düşürür; aynı asidoz yem alımını dalgalandırır ve yem dönüşümünü bozar. Kaba yem < %10, ince öğütülmüş tahıl, pelet-ağırlıklı yem, ani geçiş ve yemlik yönetimi (aç kalıp aşırı yüklenme) ana nedendir.", "eff": "Kesimde karaciğer ıskartası (%10–30), ağır apseli hayvanlarda günlük artış −%5–10 ve karkas ağırlığı −5–10 kg; yem dönüşümünde kayıp; rumen duvarında kalıcı hasar; nadiren apse patlaması ve ölüm.", "sign": "Canlıyken belirti az: sürüde düzensiz büyüme, asidoz belirtileri (sulu dışkı, yem seçme), bazen ateş ve iştahsızlık; kesin bulgu kesimhanede karaciğer apsesi oranıdır (kesimhane geri bildirimi isteyin). Rasyonda kaba yem %10'un altında mı, tahıl ince mi, nişasta > %40 mı, geçiş kaç günde yapılıyor?", "mgmt": "Kaba yem ≥ %10–15 KM (uzun saman/ot), tahıl kaba kırılmış veya bütün (arpa bütün verilebilir), 2–3 haftalık kademeli geçiş, yemlik 23 saat dolu ve günde 2–3 öğün, su serbest, ani değişiklik yok, iyonofor ve gerekirse tilosin (antibiyotik — reçeteli, kalıntı süresine dikkat).", "info": "Monensin yem dönüşümünü %5–8 iyileştirir, asidoz ve şişmeyi azaltır; AB'de yasak, ABD'de yaygın, Türkiye'de reçeteli (300 mg/baş/gün veya 20–30 g/ton). Tilosin karaciğer apsesini %70 azaltır ama antibiyotik direnci ve kalıntı kuralları nedeniyle veteriner kararıdır. Canlı maya ve tamponlar (bikarbonat %0,75) rumen pH'ını yükseltir; organik çinko bağışıklık ve ayak sağlığını destekler. Asıl koruma kaba yem ve geçiş yönetimidir."}, "bakir": {"why": "Koyun bakırı safrayla atamaz: fazlası karaciğerde haftalar-aylar boyunca sessizce birikir. Bir stres (kırkım, nakil, kuzulama, hava değişimi, açlık) karaciğerden ani bakır salınımına yol açar; kana geçen bakır alyuvarları patlatır (hemoliz) → sarılık, böbrek yetmezliği, ölüm. Kaynaklar: sığır yemi/premiksi (Cu 15–30 mg/kg), bakır sülfatlı yalama taşı, ayak banyosu suyu içme, bakırlı gübre kalıntılı mera, molibden ve kükürt düşük rasyon (bu ikisi bakırı bağlayıp korur). Irk farkı: Teksel ve bazı et ırkları daha duyarlı.", "eff": "Kriz başladıktan sonra ölüm 1–3 günde ve çoğu zaman sürünün birkaç hayvanında birden; tedavi şansı düşük. Kronik birikim döneminde verim kaybı sessizdir. Sürüde yem kaynaklı ise haftalar içinde birden fazla ölüm görülür.", "sign": "Ani halsizlik, sürüden ayrılma, susuzluk, mukozalarda ve göz akında sarılık, koyu kahverengi-kırmızı idrar (hemoglobin), solunum hızlanması, 24–72 saatte ölüm. Ölen hayvanda sarı dokular, siyahımsı böbrek, bronz-sarı karaciğer. Rasyon Cu > 10–12 mg/kg mı, sığır yemi/premiksi kullanılıyor mu, Mo < 1 mg/kg mı? Kan/karaciğer bakır analizi (veteriner); sürüde erken belirtisiz ölümlerde mutlaka düşünün.", "mgmt": "Koyuna yalnızca koyun yemi ve koyun premiksi (Cu ≤ 10 mg/kg; Teksel için 5–8), sığır yalama taşlarını uzak tutun, ayak banyosu suyuna erişimi engelleyin, stresi azaltın (kırkım ve nakli sıcak ve aç dönemlerde yapmayın), şüphede yemi hemen değiştirin ve veteriner çağırın.", "info": "Molibden ve kükürt rumende tiyomolibdat oluşturup bakırı bağlar: koruyucu olarak amonyum molibdat (50–100 mg/gün) + sodyum sülfat (1 g/gün) veteriner denetiminde verilir; tedavide D-penisillamin/ammonium tetrathiomolybdate enjeksiyonu (veteriner). E vitamini ve selenyum oksidatif hasara karşı destektir. Tersine, bakır eksikliği (yapağı bozulması, kuzuda ataksi-'swayback') de görülür: bu yüzden koyunda bakır 'ne çok ne az' dengesidir ve koyuna özel premiks şarttır."}, "beyazkas": {"why": "Selenyum (glutatyon peroksidaz) ve E vitamini kas hücrelerini oksidatif hasardan korur. Gebe annenin rasyonu Se-E fakirse yavru doğumda bu depolarla doğmaz; hızlı büyüyen kas (iskelet) ve kalp kası hücreleri parçalanır, beyazımsı çizgiler (kireçlenme) oluşur. Türkiye'nin volkanik olmayan birçok bölgesinde toprak ve kaba yem Se düşüktür; saman, eski silaj ve yağlı tohumlar E vitamini de fakirdir; nemli depolanan tahıl E vitaminini kaybeder. Hızlı büyüme (iyi süt veren anne) ve soğuk stres riski artırır.", "eff": "Kalp formu: ani ölüm (1–7 günlük veya kuzulama sonrası koşma sonrası), iskelet formu: ayağa kalkamayan, emmeyen yavru → açlık ve pnömoni; sürüde kuzu/buzağı kayıpları %10–30'a çıkabilir. Annede retensiyo ve mastitis artışı aynı eksikliğin işaretidir.", "sign": "Yavru doğumda zayıf, 1–8 haftada sert yürüyüş, kamburluk, titreme, ayağa kalkamama (ön bacaklar açık), emme güçsüzlüğü, hızlı solunum (kalp), ani ölüm; büyük kuzularda koşturulunca yığılma. Kan selenyum/GSH-Px ve E vitamini (veteriner), anne rasyonunda Se ve E, bölgenin toprak selenyumu. Retensiyo oranı ve kuzu/buzağı ölüm nedenleri (kesim: kaslarda beyaz çizgiler).", "mgmt": "Gebeliğin son 6 haftasında annelere Se-E destekli mineral, doğumda yavruya Se+E enjeksiyonu (bölge Se fakirse rutin; veteriner), kolostrum yönetimi, taze yeşil yem/iyi kaliteli kuru ot, yağlı tohumlar ve E vitamini kaybı olmasın diye kuru depolama, aşırı hızlı büyütme döneminde ek E vitamini.", "info": "Selenyum sınırı dardır: ihtiyaç 0,3 mg/kg, zehirlenme 2–5 mg/kg; bu yüzden premiksle verilir, asla saf sodyum selenit tartılmaz. Organik Se (selenyum mayası) karaciğer ve kolostruma daha iyi geçer: kuzu için anneye gebelikte verilmesi, kuzuya enjeksiyondan daha kalıcı koruma sağlar. E vitamini 1 IU = 1 mg dl-α-tokoferol asetat; koyun 100–300 IU/gün, close-up inek 2.000 IU/gün. Bu ikili ayrıca bağışıklık (pnömoni, ishal direnci) için de temeldir."}, "buzishal": {"why": "Buzağı ishalinin ilk 3 haftadaki etkenleri: 1–5 gün E. coli (K99), 5–15 gün rota/korona virüs, 7–21 gün kriptosporidium, 2 haftadan sonra koksidiyoz ve salmonella. Ama kapıyı açan beslemedir: kolostrum yetersizliği (ilk 2 saatte 3–4 L, IgG), soğuk-düzensiz-fazla süt tek öğünde (abomazumdan hızlı geçiş), kalitesiz ikame (bitkisel protein), kirli kova-emzik, ani ikame/süt değişimi, soğuk-ıslak barınak. İshalin öldürücü tarafı enfeksiyon değil, su-elektrolit kaybı ve asidozdur (bikarbonat kaybı).", "eff": "Buzağı ölümlerinin %50'si ishaldir; hayatta kalanlarda büyüme 2–4 hafta geriler, pnömoni riski artar, düve ilk doğum yaşı uzar ve ilk laktasyon verimi düşer. Kriptosporidium insana da bulaşır.", "sign": "Sulu-sarı-beyaz dışkı, kanlı ise koksidi/salmonella; dehidrasyon: göz çökük, deri kıvrımı > 2 saniye dönmüyor, burun kuru, ayakta duramama (%8 kayıp: acil), soğuk ekstremiteler, emme refleksi kayıp. Kolostrum kontrolü: 2–7 günlük buzağıda kan total protein (> 5,5 g/dl), Brix refraktometre ile kolostrum kalitesi (> 22). Süt sıcaklığı 38–39 °C mi, öğünler düzenli mi, ikame etiketi (süt proteini mi bitkisel mi)?", "mgmt": "Kolostrum: ilk 2 saatte canlı ağırlığın %10'u (4 L), kalite ölçümü; temiz doğum bölmesi, bireysel kulübe/kuru yatak, kova-emzik günlük dezenfeksiyon, süt 2–3 öğün sabit saat ve sıcaklık, su serbest (ilk günden), starter taze; ishalli buzağıda süt kesilmez, aralara elektrolit; antibiyotik yalnızca ateşli/kanlı olguda (veteriner); kriptosporidium için halofuginon, koksidi için toltrazuril (veteriner).", "info": "Oral elektrolit: sodyum (90–130 mmol/L), glikoz, alkalileştirici (bikarbonat/asetat/propiyonat) ve glisin içermeli; 2 L'de 1 paket, günde 2–4 kez, süt öğünlerinden en az 1 saat ayrı (bikarbonatlı ürün sütün pıhtılaşmasını bozar). Ayakta duramayan buzağı damar içi serum ister. Probiyotikler (Lactobacillus, Bacillus, maya) sütle verilince ishal sıklığını %20–30 azaltır; E. coli K99 aşısı anneye (gebelik sonunda) kolostrum yoluyla koruma sağlar. Starter yemde bağırsak sağlığı için maya kültürü ve organik asitler kullanılır."}, "buzpnomo": {"why": "Buzağı solunum hastalığı (BRD) üç ayaklıdır: etken (Pasteurella/Mannheimia, Mycoplasma, BRSV, IBR, PI3 virüsleri), çevre (amonyak > 10 ppm, nem, cereyan, kalabalık, sıcak-soğuk dalgalanması, toz) ve direnç (kolostrum, A-E vitamini, selenyum, çinko, bakır, enerji). Kolostrumla alınan antikorlar 2–3 ayda biter; bu dönemde (sütten kesim stresiyle birlikte) hastalık zirve yapar. A vitamini solunum yolu epitelini (mukus, silya) korur; E-Se ve Zn-Cu savunma hücrelerini güçlendirir.", "eff": "Ölüm %5–15; iyileşenlerde akciğer hasarı kalıcı: günlük artış −%10–20, düve ilk doğum yaşı gecikir, ilk laktasyon sütü −500 kg, ayıklama riski 2 kat. Tedavi antibiyotik ve iş gücü maliyeti yüksektir.", "sign": "Öksürük (özellikle sabah ve hareketle), burun akıntısı (önce şeffaf sonra irinli), hızlı solunum (> 40/dk), ateş > 39,5 °C, kulak düşüklüğü, iştahsızlık, göz akıntısı; dinlemede akciğer sesleri (veteriner). Sürü taraması: günlük ateş ölçümü riskli dönemde (sütten kesim ±2 hafta), Wisconsin skorlama kartı. Barınak: amonyak kokusu burnunuzu yakıyorsa > 25 ppm; nem, yatak ıslaklığı, buzağı başına alan (< 2 m² riskli). Kolostrum durumu (total protein).", "mgmt": "Kolostrum yönetimi, kuru-havadar-cereyansız barınak (hava değişimi var, taslak yok), buzağı başına 2,5–3 m², grup yaşı farkı < 2 hafta, sütten kesimi kademeli ve stresleri (boynuz, nakil, aşı) aynı güne yığmamak, aşı programı (IBR, BRSV, PI3, Mannheimia — veteriner), erken tanı ve tedavi (ilk 24 saat).", "info": "A vitamini starter yemde 10.000 IU/kg, E vitamini 50–100 IU/kg, Se 0,3 mg/kg, Zn 60–80 mg/kg, Cu 15 mg/kg (NASEM 2021). Sütle beslenen buzağıda ikame yeminin vitamin profili belirleyicidir; tam yağlı sütle büyüyenlerde A ve E vitamini süt kalitesine bağlıdır, kış sonu düşüktür. Enjekte A-D-E (veteriner) stres dönemlerinde hızlı destektir. Probiyotik ve maya hücre duvarı (MOS) bağırsak bağışıklığı üzerinden solunum direncini de artırır."}, "yapagi": {"why": "Tüy ve yapağı keratin proteinidir; keratin sentezi kükürtlü amino asitler (metiyonin, sistein), çinko (keratinosit bölünmesi), bakır (keratin disülfit bağları ve pigment — tirozinaz enzimi), iyot (tiroit hormonu tüy döngüsünü yönetir) ve biotin (yağ asidi sentezi, deri bariyeri) gerektirir. Bakır eksikliğinde siyah tüy kızıllaşır, gözlük görünümü olur, yapağı kıvrımı kaybolur ('çelik yün'); çinko eksikliğinde deri kalınlaşır, pul pul dökülür (parakeratoz), tüy kopar; iyot eksikliğinde tüy seyrek-kaba ve guatr; protein-enerji yetersizliğinde yapağı incelir ve kopar (açlık çizgisi). Parazitler (bit, uyuz) ve mantar ayırıcı tanıdır.", "eff": "Mat-kaba tüy çoğu zaman 'görünmeyen' mineral eksikliğinin ilk işaretidir: aynı eksiklik bağışıklık, döl verimi ve büyümeyi de düşürür. Koyunda yapağı veriminde %10–20 kayıp ve kalite düşüşü (kırılgan, kıvrımsız), deri hastalıklarına açıklık.", "sign": "Tüy mat, kaba, uzun ve kışlık tüyün ilkbaharda atılamaması (kronik eksiklik veya parazit), siyah tüyde kızıl-kahve dönüşüm ve göz çevresi açık renk (Cu), boyun-bacaklarda kalın pul pul deri ve kaşıntısız tüy kaybı (Zn), guatr-şişkin boyun ve seyrek tüylü zayıf yavru (I), yapağıda 'açlık çizgisi' kopma noktası (besleme krizi), tırnak çatlakları birlikteyse biotin/Zn. Rasyon Zn, Cu, I ve S düzeyleri, parazit kontrolü (bit, uyuz: kaşıntı var), mantar (ringworm: yuvarlak alanlar).", "mgmt": "Parazit programı (bit/uyuz için havuz-ilaç), ahır nemi ve kalabalık, protein-enerji yeterli rasyon, koyunda kırkım sonrası ve gebelikte mineral desteği, tuz-mineral yalama tüketimini ölçün, tüy değişimi mevsiminde (bahar) iz mineral ve biotin takviyesi.", "info": "Organik (kelatlı) çinko ve bakır inorganik tuzlara göre %20–40 daha iyi emilir ve antagonistlerden (Ca, Fe, Mo, S) daha az etkilenir; tüy-tırnak-deri sorunlarında tercih edilir. Koyunda yapağı için kükürt %0,2–0,25 (metiyonin-sisteinin ham maddesi) ve bakır dikkatle (5–10 mg/kg): yapağı için biraz bakır gerekir, fazlası zehirlidir — koyuna özel premiks kullanın. Biotin tırnak ve deri için 10–20 mg/gün (sığır), 2–6 mg (koyun). Etki 6–10 hafta (yeni tüy/yapağı büyümesi)."}};
